def scaled_dot_product_attention(Q, K, V):
    d_k = K.size(-1)
    scores = torch.bmm(Q, K.transpose(1, 2)) / math.sqrt(d_k)
    weights = torch.softmax(scores, dim=-1)
    return torch.bmm(weights, V)

import torch
import torch.nn.functional as F

def binary_cross_entropy(logits, targets, pos_weight=None):
    if logits.shape != targets.shape:
        raise ValueError(f"shape mismatch: {tuple(logits.shape)} vs {tuple(targets.shape)}")
    weight = 1.0 if pos_weight is None else pos_weight
    per_element = weight * targets * F.softplus(-logits) + (1 - targets) * F.softplus(logits)
    return per_element.mean()

def cross_entropy_loss(logits, targets):
    log_probs = logits - torch.logsumexp(logits, dim=-1, keepdim=True)
    return -log_probs[torch.arange(targets.shape[0]), targets].mean()

class MyDropout(nn.Module):
    def __init__(self, p=0.5):
        super().__init__()
        self.p = p

    def forward(self, x):
        if not self.training or self.p == 0:
            return x
        mask = (torch.rand_like(x) > self.p).float()
        return x * mask / (1 - self.p)

class MyEmbedding(nn.Module):
    def __init__(self, num_embeddings, embedding_dim):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(num_embeddings, embedding_dim))

    def forward(self, indices):
        return self.weight[indices]

def flow_matching_loss(model_output, x0, x1, t):
    target_velocity = x1 - x0
    diff = model_output - target_velocity
    return (diff * diff).mean()

def clip_grad_norm(parameters, max_norm):
    parameters = [p for p in parameters if p.grad is not None]
    total_norm = torch.sqrt(sum(p.grad.norm() ** 2 for p in parameters))
    clip_coef = max_norm / (total_norm + 1e-6)
    if clip_coef < 1:
        for p in parameters:
            p.grad.mul_(clip_coef)
    return total_norm.item()

def graph_readout(X, batch, mode='mean'):
    import torch
    num_graphs = batch.max().item() + 1
    D = X.shape[1]
    if mode == 'sum':
        out = torch.zeros(num_graphs, D)
        out.index_add_(0, batch, X)
        return out
    elif mode == 'mean':
        out = torch.zeros(num_graphs, D)
        out.index_add_(0, batch, X)
        count = torch.zeros(num_graphs)
        count.index_add_(0, batch, torch.ones(batch.shape[0]))
        return out / count.unsqueeze(1)
    elif mode == 'max':
        out = torch.full((num_graphs, D), float('-inf'))
        for i in range(num_graphs):
            mask = batch == i
            out[i] = X[mask].max(dim=0).values
        return out
    else:
        raise ValueError(f"Unsupported mode: {mode}")

def pass_at_k(num_samples, num_correct, k):
    if not num_samples or len(num_samples) != len(num_correct):
        raise ValueError("need one correct count per problem")
    if k < 1:
        raise ValueError("k must be at least 1")
    total = 0.0
    for n, c in zip(num_samples, num_correct):
        if n < k or c < 0 or c > n:
            raise ValueError("need k <= n and 0 <= c <= n")
        if n - c < k:
            total += 1.0
            continue
        miss = 1.0
        for i in range(n - c + 1, n + 1):
            miss *= 1.0 - k / i
        total += 1.0 - miss
    return total / len(num_samples)

import torch


def per_token_logprobs(logits, input_ids):
    log_probs = torch.log_softmax(logits, dim=-1)
    return torch.gather(log_probs, dim=-1, index=input_ids.unsqueeze(-1)).squeeze(-1)

import torch


def response_token_mask(prompt_lens, total_lens, max_len):
    if prompt_lens.shape != total_lens.shape:
        raise ValueError(
            f"shape mismatch: {tuple(prompt_lens.shape)} vs {tuple(total_lens.shape)}"
        )
    if not isinstance(max_len, int) or max_len <= 0:
        raise ValueError(f"max_len must be a positive integer, got {max_len!r}")
    if (prompt_lens < 0).any() or (total_lens < prompt_lens).any() or (total_lens > max_len).any():
        raise ValueError("every row must satisfy 0 <= prompt_lens <= total_lens <= max_len")
    positions = torch.arange(max_len, device=prompt_lens.device).unsqueeze(0)
    return (positions >= prompt_lens.unsqueeze(-1)) & (positions < total_lens.unsqueeze(-1))

import torch

def rloo_advantage(rewards, group_size):
    if rewards.ndim != 1 or group_size < 2 or rewards.numel() % group_size != 0:
        raise ValueError("rewards must be 1-D and group_size >= 2 must divide its length")
    grouped = rewards.reshape(-1, group_size)
    baseline = (grouped.sum(dim=1, keepdim=True) - grouped) / (group_size - 1)
    return (grouped - baseline).reshape(-1)

def my_softmax(x: torch.Tensor, dim: int = -1) -> torch.Tensor:
    x_max = x.max(dim=dim, keepdim=True).values
    e_x = torch.exp(x - x_max)
    return e_x / e_x.sum(dim=dim, keepdim=True)

def regularized_loss(data_loss, named_parameters, l1=0.0, l2=0.0):
    if l1 < 0 or l2 < 0:
        raise ValueError("regularization strengths must be non-negative")
    loss = data_loss
    for _name, weight in named_parameters:
        if weight.ndim < 2:
            continue
        loss = loss + l1 * weight.abs().sum() + 0.5 * l2 * (weight * weight).sum()
    return loss

import torch.utils.checkpoint as cp

def checkpoint_sequential(fns, x):
    for fn in fns:
        x = cp.checkpoint(fn, x, use_reentrant=False)
    return x

class MyAdam:
    def __init__(self, params, lr=1e-3, betas=(0.9, 0.999), eps=1e-8):
        self.params = list(params)
        self.lr = lr
        self.beta1, self.beta2 = betas
        self.eps = eps
        self.t = 0
        self.m = [torch.zeros_like(p) for p in self.params]
        self.v = [torch.zeros_like(p) for p in self.params]

    def step(self):
        self.t += 1
        with torch.no_grad():
            for i, p in enumerate(self.params):
                if p.grad is None:
                    continue
                self.m[i] = self.beta1 * self.m[i] + (1 - self.beta1) * p.grad
                self.v[i] = self.beta2 * self.v[i] + (1 - self.beta2) * p.grad ** 2
                m_hat = self.m[i] / (1 - self.beta1 ** self.t)
                v_hat = self.v[i] / (1 - self.beta2 ** self.t)
                p -= self.lr * m_hat / (torch.sqrt(v_hat) + self.eps)

    def zero_grad(self):
        for p in self.params:
            if p.grad is not None:
                p.grad.zero_()

def beam_search(log_prob_fn, start_token, max_len, beam_width, eos_token):
    beams = [(0.0, [start_token])]
    completed = []
    for _ in range(max_len):
        candidates = []
        for score, seq in beams:
            if seq[-1] == eos_token:
                completed.append((score, seq))
                continue
            log_probs = log_prob_fn(torch.tensor(seq))
            topk_lp, topk_idx = log_probs.topk(beam_width)
            for j in range(beam_width):
                candidates.append((score + topk_lp[j].item(), seq + [topk_idx[j].item()]))
        if not candidates:
            break
        candidates.sort(key=lambda x: x[0], reverse=True)
        beams = candidates[:beam_width]
    all_seqs = completed + beams
    all_seqs.sort(key=lambda x: x[0], reverse=True)
    return all_seqs[0][1]

import torch

def confidence_calibration(confidences, correct, bins=10):
    if (confidences.ndim != 1 or correct.ndim != 1 or confidences.shape != correct.shape
            or confidences.numel() == 0 or not isinstance(bins, int) or isinstance(bins, bool) or bins <= 0):
        raise ValueError("invalid shape or bins")
    if (not torch.isfinite(confidences).all() or (confidences < 0).any() or (confidences > 1).any()
            or not torch.isfinite(correct).all() or ((correct != 0) & (correct != 1)).any()):
        raise ValueError("invalid probabilities or labels")
    labels = correct.to(confidences.dtype)
    bucket = (confidences * bins).long().clamp(max=bins - 1)
    ece = confidences.new_zeros(())
    for index in range(bins):
        chosen = bucket == index
        if chosen.any():
            ece = ece + chosen.float().mean() * (confidences[chosen].mean() - labels[chosen].mean()).abs()
    return {"accuracy": labels.mean().item(), "brier": ((confidences - labels) ** 2).mean().item(), "ece": ece.item()}

def cosine_lr_schedule(step, total_steps, warmup_steps, max_lr, min_lr=0.0):
    if step < warmup_steps:
        return max_lr * step / warmup_steps
    if step >= total_steps:
        return min_lr
    progress = (step - warmup_steps) / (total_steps - warmup_steps)
    return min_lr + 0.5 * (max_lr - min_lr) * (1.0 + math.cos(math.pi * progress))

import torch


def dapo_dynamic_sampling(rewards, group_size, tol=0.0):
    if not isinstance(group_size, int) or group_size <= 0:
        raise ValueError(f"group_size must be a positive integer, got {group_size!r}")
    if rewards.numel() % group_size != 0:
        raise ValueError(
            f"group_size {group_size} does not divide {rewards.numel()} rewards"
        )
    if tol < 0:
        raise ValueError(f"tol must be non-negative, got {tol}")

    grouped = rewards.reshape(-1, group_size)
    spread = grouped.max(dim=-1).values - grouped.min(dim=-1).values
    keep = spread > tol
    return keep.repeat_interleave(group_size)

def sparse_ffn_forward(x, expert_indices, expert_weights, experts):
    if x.ndim != 2 or expert_indices.ndim != 2 or expert_weights.shape != expert_indices.shape:
        raise ValueError("x and route tensors have invalid shapes")
    if expert_indices.shape[0] != x.shape[0] or expert_indices.dtype != torch.long:
        raise ValueError("route tensors must align with tokens and indices must be long")
    if not experts:
        raise ValueError("at least one expert is required")
    if expert_indices.numel() and (int(expert_indices.min()) < 0 or int(expert_indices.max()) >= len(experts)):
        raise ValueError("expert index out of range")
    routes = [[] for _ in experts]
    for token in range(expert_indices.shape[0]):
        for slot in range(expert_indices.shape[1]):
            routes[int(expert_indices[token, slot])].append((token, slot))
    output = torch.zeros_like(x)
    for expert_id, accepted in enumerate(routes):
        if not accepted:
            continue
        token_ids = torch.tensor([token for token, _ in accepted], device=x.device)
        slot_ids = torch.tensor([slot for _, slot in accepted], device=x.device)
        expert_output = experts[expert_id](x.index_select(0, token_ids))
        route_weights = expert_weights[token_ids, slot_ids].to(expert_output.dtype).unsqueeze(-1)
        output.index_add_(0, token_ids, expert_output * route_weights)
    return output

def dpo_loss(policy_chosen_logps, policy_rejected_logps,
             ref_chosen_logps, ref_rejected_logps, beta=0.1):
    chosen_rewards = beta * (policy_chosen_logps - ref_chosen_logps)
    rejected_rewards = beta * (policy_rejected_logps - ref_rejected_logps)
    diff = chosen_rewards - rejected_rewards
    return -torch.log(torch.sigmoid(diff)).mean()

import asyncio
import inspect


class EventBus:
    def __init__(self):
        self._hooks = {}

    def on(self, name, listener, prepend=False):
        hooks = self._hooks.setdefault(name, [])
        record = [listener]
        if prepend:
            hooks.insert(0, record)
        else:
            hooks.append(record)

        def dispose():
            for i, item in enumerate(hooks):
                if item is record:
                    del hooks[i]
                    return True
            return False

        return dispose

    def once(self, name, listener, prepend=False):
        def wrapper(*args):
            dispose()
            return listener(*args)

        dispose = self.on(name, wrapper, prepend)
        return dispose

    def _snapshot(self, name):
        return [record[0] for record in self._hooks.get(name, [])]

    @staticmethod
    def _bailed(value):
        return value is not None and value is not False

    def emit(self, name, *args):
        for listener in self._snapshot(name):
            listener(*args)

    def bail(self, name, *args):
        for listener in self._snapshot(name):
            result = listener(*args)
            if self._bailed(result):
                return result
        return None

    async def serial(self, name, *args):
        for listener in self._snapshot(name):
            result = listener(*args)
            if inspect.isawaitable(result):
                result = await result
            if self._bailed(result):
                return result
        return None

    async def parallel(self, name, *args):
        async def run(listener):
            result = listener(*args)
            if inspect.isawaitable(result):
                await result

        results = await asyncio.gather(*(run(l) for l in self._snapshot(name)), return_exceptions=True)
        errors = [r for r in results if isinstance(r, BaseException)]
        if errors:
            raise ExceptionGroup(f"{len(errors)} listener(s) of {name!r} failed", errors)

    def waterfall(self, name, *args, inner):
        queue = self._snapshot(name)

        def next():
            if queue:
                return queue.pop(0)(*args, next)
            return inner(*args)

        return next()

MESSAGE_TYPES = {"system/message", "user/message", "assistant/message", "tool/result"}


def _without_content(data):
    return {**data, "message": {**data["message"], "content": None}}


def fold_surface(events):
    nodes = []
    replacements = []
    for index, event in enumerate(events):
        seq = event["seq"]
        if seq != index:
            raise ValueError(f"seq {seq} is not contiguous; expected {index}")
        op = event.get("surface_op")
        if event["type"] not in MESSAGE_TYPES:
            if op is not None:
                raise ValueError(f"{event['type']} cannot carry a surface_op")
            continue
        if op is None:
            raise ValueError(f"{event['type']} requires a surface_op")
        if op == "append":
            nodes.append(seq)
            continue
        if not (isinstance(op, dict) and op.get("op") == "replace"
                and isinstance(op.get("start_seq"), int) and isinstance(op.get("end_seq"), int)):
            raise ValueError("invalid surface_op")
        start, end = op["start_seq"], op["end_seq"]
        if start >= seq or end >= seq:
            raise ValueError("replace must reference earlier events")
        if start not in nodes or end not in nodes:
            raise ValueError("replace range is not on the current surface")
        start_idx, end_idx = nodes.index(start), nodes.index(end)
        if start_idx > end_idx:
            raise ValueError("replace start comes after its end")
        shadowed = nodes[start_idx:end_idx + 1]
        if event["type"] == "tool/result":
            if len(shadowed) != 1 or events[shadowed[0]]["type"] != "tool/result":
                raise ValueError("a tool/result replace must rewrite exactly one tool/result")
            if _without_content(events[shadowed[0]]["data"]) != _without_content(event["data"]):
                raise ValueError("a tool/result replace may change only content")
        if start_idx == 0 and events[nodes[0]]["type"] == "system/message":
            if event["type"] != "system/message" or len(shadowed) != 1:
                raise ValueError("the system prompt at node 0 may only be replaced by one system/message")
        nodes[start_idx:end_idx + 1] = [seq]
        replacements.append({"seq": seq, "start": start, "end": end, "shadowed": shadowed})
    return {
        "nodes": list(nodes),
        "messages": [events[s]["data"]["message"] for s in nodes],
        "replacements": replacements,
    }

CAUSES = ("interrupted", "forked")


def open_turn_closers(events, cause="interrupted"):
    if cause not in CAUSES:
        raise ValueError(f"unknown cause {cause!r}")
    open_turn = None
    open_step = None
    pending = {}
    for event in events:
        kind, data = event["type"], event["data"]
        if kind in ("turn/start", "turn/end", "step/end"):
            pending.clear()
        if kind == "turn/start":
            open_turn, open_step = data["turn"], None
        elif kind == "turn/end":
            open_turn, open_step = None, None
        elif kind == "step/start":
            open_step = data["step"]
        elif kind == "step/end":
            open_step = None
        elif kind == "assistant/message":
            for call_id in data["tool_call_ids"]:
                pending[call_id] = {"turn": data["turn"], "step": data["step"], "call_seq": None}
        elif kind == "tool/call":
            entry = pending.get(data["call_id"])
            if entry is not None:
                entry["call_seq"] = event["seq"]
        elif kind == "tool/result":
            entry = pending.get(data["call_id"])
            if (entry is not None and data["surface_op"] == "append"
                    and entry["turn"] == data["turn"] and entry["step"] == data["step"]):
                del pending[data["call_id"]]

    if not events or open_turn is None:
        return []
    last = events[-1]
    seq, time = last["seq"], last["time"]
    closers = []
    for call_id, entry in pending.items():
        seq += 1
        started = entry["call_seq"] is not None
        result = {
            "turn": entry["turn"], "step": entry["step"], "call_id": call_id, "surface_op": "append",
            "is_error": True, "started": started,
            "error_code": "TOOL_OUTCOME_UNKNOWN" if started else "TOOL_NOT_STARTED",
        }
        if started:
            result["source_event_seqs"] = [entry["call_seq"]]
        closers.append({"type": "tool/result", "seq": seq, "time": time, "data": result})
    if open_step is not None:
        seq += 1
        closers.append({"type": "step/end", "seq": seq, "time": time, "data": {"turn": open_turn, "step": open_step}})
    seq += 1
    closers.append({"type": "turn/end", "seq": seq, "time": time, "data": {"turn": open_turn, "reason": {"kind": cause}}})
    return closers

import json
import re

GENTLE = ("You are repeating the exact same tool call with identical arguments. "
          "Carefully analyze the previous result before calling again: if the task is "
          "not complete, try a different approach or different arguments instead of "
          "repeating the call.")
DETAILED = ("Repeated tool call detected:\n- tool: {tool}\n- consecutive_calls: {count}\n"
            "- arguments: {preview}\nThe repeated calls are not making progress. Do not call "
            "this tool with these exact arguments again. Inspect the latest result and choose a "
            "different action, different arguments, or finish the task if enough evidence has "
            "been gathered.")


def _pattern(text):
    return re.compile(re.escape(text).replace(r"\*", ".*"))


class RepeatToolReminder:
    def __init__(self, thresholds=(3, 5, 8), include=(), exclude=(), arguments_preview_chars=500):
        values = list(thresholds)
        if not values:
            raise ValueError("thresholds must not be empty")
        for value in values:
            if type(value) is not int or value < 2:
                raise ValueError(f"invalid threshold {value!r}")
        if len(set(values)) != len(values):
            raise ValueError("thresholds must not contain duplicates")
        if type(arguments_preview_chars) is not int or arguments_preview_chars < 1:
            raise ValueError("arguments_preview_chars must be an integer >= 1")
        self.thresholds = sorted(values)
        self.include = [_pattern(p) for p in include]
        self.exclude = [_pattern(p) for p in exclude]
        self.preview_chars = arguments_preview_chars
        self.chains = {}

    def _tracked(self, name):
        if self.include and not any(p.fullmatch(name) for p in self.include):
            return False
        return not any(p.fullmatch(name) for p in self.exclude)

    def _observe(self, agent, name, arguments):
        if agent is None or not self._tracked(name):
            return None
        canonical = json.dumps(arguments, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        key = (name, canonical)
        chain = self.chains.get(agent)
        count = chain[1] + 1 if chain is not None and chain[0] == key else 1
        self.chains[agent] = (key, count)
        if count not in self.thresholds:
            return None
        if count == self.thresholds[0]:
            text = GENTLE
        else:
            preview = canonical
            if len(canonical) > self.preview_chars:
                preview = f"{canonical[:self.preview_chars]}… (+{len(canonical) - self.preview_chars} more chars)"
            text = DETAILED.format(tool=name, count=count, preview=preview)
        return {"summary": f"{name} × {count}", "text": text}

    def post_execute(self, agent, tool_name, arguments, next):
        reminder = self._observe(agent, tool_name, arguments)
        downstream = next()
        if reminder is None:
            return downstream
        return {**downstream, "additional_contexts": [reminder, *downstream.get("additional_contexts", [])]}

    def on_user_message(self, agent):
        self.chains.pop(agent, None)

def reconcile_system_prompt(system_nodes, rendered, in_history_capable, new_series):
    seqs = [seq for seq, _ in system_nodes]
    if len(set(seqs)) != len(seqs):
        raise ValueError("duplicate system node seqs")
    if not system_nodes:
        return [("append", rendered)]
    head_seq, head_text = system_nodes[0]
    later = [(seq, text) for seq, text in system_nodes[1:] if text]

    def consolidate(target):
        ops = [("replace", seq, "") for seq, _ in later]
        if head_text != target:
            ops.append(("replace", head_seq, target))
        return ops

    if rendered == "":
        return consolidate("")
    if in_history_capable and not new_series:
        effective = next((text for _, text in reversed(system_nodes) if text), None)
        return [] if effective == rendered else [("append", rendered)]
    return consolidate(rendered)

MARKER = "\n\n[... tool result middle pruned ...]\n\n"


def prune_content(blocks, threshold_chars=8192, head_chars=4096, tail_chars=1024):
    if type(threshold_chars) is not int or threshold_chars <= 0:
        raise ValueError("threshold_chars must be a positive integer")
    for name, value in (("head_chars", head_chars), ("tail_chars", tail_chars)):
        if type(value) is not int or value < 0:
            raise ValueError(f"{name} must be a non-negative integer")
    if head_chars + len(MARKER) + tail_chars > threshold_chars:
        raise ValueError("head_chars + marker + tail_chars must fit within threshold_chars")

    total = sum(len(block["text"]) for block in blocks if block["type"] == "text")
    if total <= threshold_chars:
        return None

    removed_start = head_chars
    removed_end = total - tail_chars
    pruned = []
    consumed = 0
    marker_placed = False
    for block in blocks:
        if block["type"] != "text":
            pruned.append(block)
            continue
        text = block["text"]
        start, end = consumed, consumed + len(text)
        head_end = min(len(text), max(0, removed_start - start))
        tail_start = min(len(text), max(0, removed_end - start))
        marker = ""
        if start < removed_end and end > removed_start and not marker_placed:
            marker, marker_placed = MARKER, True
        new_text = text[:head_end] + marker + text[tail_start:]
        if new_text:
            pruned.append({**block, "text": new_text})
        consumed = end
    return pruned

import torch


def group_relative_advantage(rewards, group_size, eps=1e-4):
    if not isinstance(group_size, int) or group_size <= 0:
        raise ValueError(f"group_size must be a positive integer, got {group_size!r}")
    if rewards.numel() % group_size != 0:
        raise ValueError(
            f"group_size {group_size} does not divide {rewards.numel()} rewards"
        )
    grouped = rewards.reshape(-1, group_size)
    mean = grouped.mean(dim=-1, keepdim=True)
    std = grouped.std(dim=-1, unbiased=False, keepdim=True)
    return ((grouped - mean) / (std + eps)).reshape(-1)

import torch


def gspo_sequence_ratio(logprobs, old_logprobs, mask):
    shapes = (logprobs.shape, old_logprobs.shape, mask.shape)
    if len(set(shapes)) != 1:
        raise ValueError(f"all tensors must share a shape, got {shapes}")

    keep = mask.to(logprobs.dtype)
    log_ratio = (logprobs - old_logprobs) * keep
    count = keep.sum(dim=-1)
    mean_log_ratio = log_ratio.sum(dim=-1) / count.clamp(min=1.0)
    return torch.exp(mean_log_ratio)

def hybrid_attention_schedule(Q, K, V, layer_index, window_size, global_every):
    if Q.ndim != 3 or K.ndim != 3 or V.ndim != 3:
        raise ValueError("Q, K, and V must be rank-3 tensors")
    if Q.shape[:2] != K.shape[:2] or Q.shape[:2] != V.shape[:2] or Q.shape[-1] != K.shape[-1]:
        raise ValueError("Q, K, and V batch/sequence shapes and Q/K head dimensions must match")
    if Q.shape[0] == 0 or Q.shape[1] == 0 or Q.shape[-1] == 0 or V.shape[-1] == 0:
        raise ValueError("batch, sequence, head_dim, and value_dim must be non-empty")
    if layer_index < 0 or window_size < 0 or global_every < 1:
        raise ValueError("layer_index/window_size must be non-negative and global_every positive")

    scores = torch.bmm(Q, K.transpose(1, 2)) / math.sqrt(Q.shape[-1])
    sequence = Q.shape[1]
    query_position = torch.arange(sequence, device=Q.device).unsqueeze(1)
    key_position = torch.arange(sequence, device=Q.device).unsqueeze(0)
    allowed = key_position <= query_position
    if (layer_index + 1) % global_every != 0:
        allowed = allowed & (key_position >= query_position - window_size)
    scores = scores.masked_fill(~allowed.unsqueeze(0), float("-inf"))
    return torch.bmm(torch.softmax(scores, dim=-1), V)

import torch


def k3_kl_penalty(logprobs, ref_logprobs):
    if logprobs.shape != ref_logprobs.shape:
        raise ValueError(
            f"shape mismatch: {tuple(logprobs.shape)} vs {tuple(ref_logprobs.shape)}"
        )
    log_ratio = ref_logprobs - logprobs
    return torch.exp(log_ratio) - log_ratio - 1.0

def my_layer_norm(x, gamma, beta, eps=1e-5):
    mean = x.mean(dim=-1, keepdim=True)
    var = x.var(dim=-1, keepdim=True, unbiased=False)
    x_norm = (x - mean) / torch.sqrt(var + eps)
    return gamma * x_norm + beta

class SimpleLinear:
    def __init__(self, in_features: int, out_features: int):
        self.weight = torch.randn(out_features, in_features) * (1 / math.sqrt(in_features))
        self.weight.requires_grad_(True)
        self.bias = torch.zeros(out_features, requires_grad=True)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return x @ self.weight.T + self.bias

import torch

MODES = ("token-mean", "seq-mean-token-mean", "seq-mean-token-sum", "seq-mean-token-sum-norm")

def aggregate_loss(per_token_loss, mask, mode):
    if mode not in MODES:
        raise ValueError(f"unknown mode {mode!r}")
    if per_token_loss.ndim != 2 or per_token_loss.shape != mask.shape:
        raise ValueError("per_token_loss and mask must share one (B, T) shape")
    mask = mask.bool()
    if not bool(mask.any()):
        raise ValueError("mask has no valid tokens")
    masked = torch.where(mask, per_token_loss, torch.zeros_like(per_token_loss))
    seq_sum = masked.sum(dim=1)
    seq_len = mask.sum(dim=1)
    if mode == "token-mean":
        return seq_sum.sum() / seq_len.sum()
    valid = seq_len > 0
    if mode == "seq-mean-token-mean":
        per_seq = seq_sum[valid] / seq_len[valid]
    elif mode == "seq-mean-token-sum":
        per_seq = seq_sum[valid]
    else:
        per_seq = seq_sum[valid] / mask.shape[1]
    return per_seq.mean()

import torch

def masked_perplexity(logprobs, mask):
    if logprobs.shape != mask.shape:
        raise ValueError("shape mismatch")
    valid = mask.bool()
    if not valid.any():
        raise ValueError("no valid tokens")
    return torch.exp(-logprobs[valid].mean())

class SwiGLUMLP(nn.Module):
    def __init__(self, d_model, d_ff):
        super().__init__()
        self.gate_proj = nn.Linear(d_model, d_ff)
        self.up_proj = nn.Linear(d_model, d_ff)
        self.down_proj = nn.Linear(d_ff, d_model)

    def forward(self, x):
        gate = self.gate_proj(x)
        silu_gate = gate * torch.sigmoid(gate)
        return self.down_proj(silu_gate * self.up_proj(x))

def noisy_topk_route(clean_logits, noise, noise_std, k):
    if clean_logits.ndim != 2 or not isinstance(noise, torch.Tensor) or noise.shape != clean_logits.shape:
        raise ValueError("clean_logits and noise must be matching (tokens, num_experts) tensors")
    if not clean_logits.is_floating_point():
        raise ValueError("clean_logits must be floating point")
    num_experts = clean_logits.shape[-1]
    if not isinstance(k, int) or isinstance(k, bool) or k < 1 or k > num_experts:
        raise ValueError("k must be an integer in [1, num_experts]")
    if noise_std < 0:
        raise ValueError("noise_std must be non-negative")
    noisy = clean_logits + noise_std * noise
    probs = torch.softmax(noisy, dim=-1)
    weights, indices = torch.topk(probs, k, dim=-1)
    weights = weights / weights.sum(-1, keepdim=True)
    return indices, weights

def router_z_loss(router_logits):
    if not isinstance(router_logits, torch.Tensor) or router_logits.ndim != 2:
        raise ValueError("router_logits must be a (tokens, num_experts) tensor")
    if not router_logits.is_floating_point():
        raise ValueError("router_logits must be floating point")
    log_partition = torch.logsumexp(router_logits, dim=-1)
    return log_partition.square().mean()

def shared_routed_moe(x, expert_indices, expert_weights, routed_experts, shared_experts):
    if x.ndim != 2 or expert_indices.ndim != 2 or expert_weights.shape != expert_indices.shape:
        raise ValueError("x and routed route tensors have invalid shapes")
    if expert_indices.shape[0] != x.shape[0] or expert_indices.dtype != torch.long:
        raise ValueError("routed route tensors must align with tokens and indices must be long")
    if not routed_experts:
        raise ValueError("at least one routed expert is required")
    if expert_indices.numel() and (int(expert_indices.min()) < 0 or int(expert_indices.max()) >= len(routed_experts)):
        raise ValueError("routed expert index out of range")
    routed_out = torch.zeros_like(x)
    routes = [[] for _ in routed_experts]
    for token in range(expert_indices.shape[0]):
        for slot in range(expert_indices.shape[1]):
            routes[int(expert_indices[token, slot])].append((token, slot))
    for expert_id, accepted in enumerate(routes):
        if not accepted:
            continue
        token_ids = torch.tensor([token for token, _ in accepted], device=x.device)
        slot_ids = torch.tensor([slot for _, slot in accepted], device=x.device)
        expert_output = routed_experts[expert_id](x.index_select(0, token_ids))
        route_weights = expert_weights[token_ids, slot_ids].to(expert_output.dtype).unsqueeze(-1)
        routed_out.index_add_(0, token_ids, expert_output * route_weights)
    shared_out = torch.zeros_like(x)
    for shared in shared_experts:
        shared_out = shared_out + shared(x)
    return routed_out + shared_out

def moe_topk_router(router_logits, k):
    if router_logits.ndim != 2:
        raise ValueError("router_logits must have shape (tokens, experts)")
    num_experts = router_logits.shape[-1]
    if not isinstance(k, int) or isinstance(k, bool) or not 1 <= k <= num_experts:
        raise ValueError("k must select between one and all experts")
    probabilities = torch.softmax(router_logits, dim=-1)
    weights, indices = torch.topk(probabilities, k, dim=-1)
    weights = weights / weights.sum(dim=-1, keepdim=True)
    return indices, weights

LENGTH_TEXT = ('Tool call "{}" was not executed: the response hit the output token limit, so its '
               'arguments may be truncated. Re-issue the tool call with complete arguments.')


def _run_tools(message, execute_tool):
    results, terminates = [], []
    for call in (b for b in message["content"] if b["type"] == "toolCall"):
        base = {"role": "toolResult", "tool_call_id": call["id"], "tool_name": call["name"]}
        if message["stop_reason"] == "length":
            results.append({**base, "content": [{"type": "text", "text": LENGTH_TEXT.format(call["name"])}], "is_error": True})
            terminates.append(False)
            continue
        try:
            outcome = execute_tool(call)
        except Exception as error:
            results.append({**base, "content": [{"type": "text", "text": str(error)}], "is_error": True})
            terminates.append(False)
            continue
        results.append({**base, "content": outcome["content"], "is_error": bool(outcome.get("is_error"))})
        terminates.append(bool(outcome.get("terminate")))
    return results, bool(results) and not all(terminates)


def agent_loop(prompts, model, execute_tool, get_steering, get_follow_up):
    context = list(prompts)
    new_messages = list(prompts)
    pending = get_steering()
    while True:
        more_tools = True
        while more_tools or pending:
            for message in pending:
                context.append(message)
                new_messages.append(message)
            pending = []
            reply = model(list(context))
            context.append(reply)
            new_messages.append(reply)
            if reply["stop_reason"] in ("error", "aborted"):
                return new_messages
            results, more_tools = _run_tools(reply, execute_tool)
            context.extend(results)
            new_messages.extend(results)
            pending = get_steering()
        follow = get_follow_up()
        if not follow:
            return new_messages
        pending = follow

ROLES = {"user", "assistant", "toolResult", "bashExecution", "custom", "branchSummary", "compactionSummary", "meta"}
TURN_STARTS = {"user", "bashExecution", "custom", "branchSummary", "compactionSummary"}


def find_cut_point(entries, keep_recent_tokens):
    if type(keep_recent_tokens) is not int or keep_recent_tokens < 1:
        raise ValueError("keep_recent_tokens must be a positive integer")
    for entry in entries:
        if entry["role"] not in ROLES:
            raise ValueError(f"unknown role {entry['role']!r}")
        if type(entry["tokens"]) is not int or entry["tokens"] < 0:
            raise ValueError("tokens must be a non-negative integer")

    cut_points = [i for i, e in enumerate(entries) if e["role"] not in ("toolResult", "meta")]
    if not cut_points:
        return {"first_kept_index": 0, "turn_start_index": -1, "is_split_turn": False}

    cut = cut_points[0]
    accumulated = 0
    for i in range(len(entries) - 1, -1, -1):
        tokens = entries[i]["tokens"]
        if tokens == 0:
            continue
        accumulated += tokens
        if accumulated >= keep_recent_tokens:
            cut = next((c for c in cut_points if c >= i), cut_points[-1])
            break

    while cut > 0 and entries[cut - 1]["role"] == "meta":
        cut -= 1

    if entries[cut]["role"] in TURN_STARTS:
        return {"first_kept_index": cut, "turn_start_index": -1, "is_split_turn": False}
    turn_start = next((j for j in range(cut, -1, -1) if entries[j]["role"] in TURN_STARTS), -1)
    return {"first_kept_index": cut, "turn_start_index": turn_start, "is_split_turn": turn_start != -1}

import asyncio


def _error(text, terminate=False):
    return {"content": [{"type": "text", "text": text}], "is_error": True, "terminate": terminate}


async def execute_tool_batch(calls, tools, mode="parallel", before_tool_call=None,
                             is_aborted=lambda: False, emit=lambda event: None):
    async def prepare(call):
        emit({"type": "start", "id": call["id"]})
        tool = tools.get(call["name"])
        if tool is None:
            outcome = _error(f"Tool {call['name']} not found")
        else:
            outcome = None
            if before_tool_call is not None:
                decision = await before_tool_call(call)
                if is_aborted():
                    outcome = _error("Operation aborted")
                elif decision and decision.get("block"):
                    outcome = _error(decision.get("reason") or "Tool execution was blocked",
                                     decision.get("terminate") is True)
        if outcome is not None:
            emit({"type": "end", "id": call["id"]})
        return outcome

    async def run(call, check_abort):
        if check_abort and is_aborted():
            outcome = _error("Operation aborted")
        else:
            try:
                result = await tools[call["name"]]["execute"](call["arguments"])
                outcome = {"content": result["content"], "is_error": False,
                           "terminate": result.get("terminate") is True}
            except Exception as error:
                outcome = _error(str(error))
        emit({"type": "end", "id": call["id"]})
        return outcome

    sequential = mode == "sequential" or any(
        tools.get(c["name"], {}).get("sequential") for c in calls)
    recorded = []
    if sequential:
        for call in calls:
            outcome = await prepare(call)
            if outcome is None:
                outcome = await run(call, False)
            recorded.append((call, outcome))
            if is_aborted():
                break
    else:
        pending = []
        for call in calls:
            outcome = await prepare(call)
            pending.append((call, outcome))
            if is_aborted():
                break

        async def settle(call, outcome):
            return outcome if outcome is not None else await run(call, True)

        outcomes = await asyncio.gather(*(settle(c, o) for c, o in pending))
        recorded = list(zip([c for c, _ in pending], outcomes))

    messages = [{"role": "toolResult", "tool_call_id": call["id"], "tool_name": call["name"],
                 "content": outcome["content"], "is_error": outcome["is_error"]}
                for call, outcome in recorded]
    terminate = bool(recorded) and all(outcome["terminate"] for _, outcome in recorded)
    return {"messages": messages, "terminate": terminate}

def _lines(content):
    if content == "":
        return []
    parts = content.split("\n")
    if content.endswith("\n"):
        parts.pop()
    return parts


def _size(text):
    return len(text.encode("utf-8"))


def _suffix_within(line, max_bytes):
    raw = line.encode("utf-8")
    if len(raw) <= max_bytes:
        return line
    start = len(raw) - max_bytes
    while start < len(raw) and raw[start] & 0xC0 == 0x80:
        start += 1
    return raw[start:].decode("utf-8")


def truncate_output(content, mode, max_lines=2000, max_bytes=51200):
    if mode not in ("head", "tail"):
        raise ValueError(f"unknown mode {mode!r}")
    if max_lines < 1 or max_bytes < 1:
        raise ValueError("limits must be at least 1")
    lines = _lines(content)
    total_bytes = _size(content)
    result = {"total_lines": len(lines), "total_bytes": total_bytes,
              "last_line_partial": False, "first_line_exceeds_limit": False}
    if len(lines) <= max_lines and total_bytes <= max_bytes:
        return {**result, "content": content, "truncated": False, "truncated_by": None,
                "output_lines": len(lines), "output_bytes": total_bytes}

    kept, used, truncated_by = [], 0, "lines"
    if mode == "head":
        if _size(lines[0]) > max_bytes:
            return {**result, "content": "", "truncated": True, "truncated_by": "bytes",
                    "output_lines": 0, "output_bytes": 0, "first_line_exceeds_limit": True}
        for line in lines[:max_lines]:
            cost = _size(line) + (1 if kept else 0)
            if used + cost > max_bytes:
                truncated_by = "bytes"
                break
            kept.append(line)
            used += cost
    else:
        for line in reversed(lines):
            if len(kept) >= max_lines:
                break
            cost = _size(line) + (1 if kept else 0)
            if used + cost > max_bytes:
                truncated_by = "bytes"
                if not kept:
                    kept.append(_suffix_within(line, max_bytes))
                    result["last_line_partial"] = True
                break
            kept.insert(0, line)
            used += cost
    output = "\n".join(kept)
    return {**result, "content": output, "truncated": True, "truncated_by": truncated_by,
            "output_lines": len(kept), "output_bytes": _size(output)}

class PolicyDecision:
    def __init__(self, action, context, reasons):
        from copy import deepcopy
        self.action = action
        self.context = deepcopy(context)
        self.reasons = list(reasons)


class PolicyEngine:
    def __init__(self, policies):
        if not isinstance(policies, (list, tuple)):
            raise TypeError("policies must be an ordered sequence")
        names = []
        for policy in policies:
            name = getattr(policy, "name", None)
            if not isinstance(name, str) or not name or not callable(getattr(policy, "evaluate", None)):
                raise TypeError("each policy needs a name and evaluate method")
            names.append(name)
        if len(names) != len(set(names)):
            raise ValueError("policy names must be unique")
        self._policies = tuple(policies)

    def evaluate(self, context):
        from copy import deepcopy
        from torch_judge.harness import HarnessFailure
        from torch_judge.harness.agents.protocol import copy_json

        working = copy_json(context, field="policy context JSON")
        if not isinstance(working, dict):
            raise TypeError("policy context must be a dictionary")
        transformed = False
        reasons = []
        for policy in self._policies:
            try:
                result = policy.evaluate(deepcopy(working))
            except HarnessFailure:
                raise
            except Exception as error:
                return PolicyDecision(
                    "deny",
                    working,
                    [f"{policy.name}: policy_error: {type(error).__name__}: {error}"],
                )
            valid = isinstance(result, dict)
            action = result.get("action") if valid else None
            reason = result.get("reason") if valid else None
            changes = result.get("changes") if valid else None
            if (
                action not in {"allow", "deny", "transform"}
                or (reason is not None and not isinstance(reason, str))
                or (action == "transform" and not isinstance(changes, dict))
                or (action != "transform" and changes is not None)
            ):
                return PolicyDecision(
                    "deny", working, [f"{policy.name}: invalid_policy_result"]
                )
            if action == "deny":
                return PolicyDecision(
                    "deny", working, [f"{policy.name}: {reason or 'denied'}"]
                )
            if action == "transform":
                try:
                    changes = copy_json(changes, field="policy changes JSON")
                except Exception:
                    return PolicyDecision(
                        "deny", working, [f"{policy.name}: invalid_policy_result"]
                    )
                working.update(changes)
                transformed = True
                if reason:
                    reasons.append(f"{policy.name}: {reason}")
        return PolicyDecision("transform" if transformed else "allow", working, reasons)

import torch


def ppo_value_loss(values, old_values, returns, mask, clip_eps=0.2):
    shapes = (values.shape, old_values.shape, returns.shape, mask.shape)
    if len(set(shapes)) != 1:
        raise ValueError(f"all tensors must share a shape, got {shapes}")
    if clip_eps <= 0:
        raise ValueError(f"clip_eps must be positive, got {clip_eps}")

    keep = mask.to(values.dtype)
    denominator = keep.sum()
    if denominator == 0:
        return torch.zeros((), dtype=values.dtype, device=values.device)

    clipped_value = old_values + (values - old_values).clamp(-clip_eps, clip_eps)
    unclipped_error = (values - returns) ** 2
    clipped_error = (clipped_value - returns) ** 2
    per_token = 0.5 * torch.max(unclipped_error, clipped_error)
    return (per_token * keep).sum() / denominator

import torch

def precision_recall_f1(preds, targets, average="macro"):
    if average not in ("micro", "macro", "weighted"):
        raise ValueError(f"unknown average {average!r}")
    if preds.ndim != 1 or targets.ndim != 1 or preds.shape != targets.shape or preds.numel() == 0:
        raise ValueError("preds and targets must be non-empty 1-D tensors of equal length")

    def divide(a, b):
        return a / b if b else 0.0

    classes = torch.unique(torch.cat([preds, targets])).tolist()
    counts = []
    for c in classes:
        pred_c, true_c = preds == c, targets == c
        tp = int((pred_c & true_c).sum())
        fp = int((pred_c & ~true_c).sum())
        fn = int((~pred_c & true_c).sum())
        counts.append((tp, fp, fn, int(true_c.sum())))

    if average == "micro":
        tp, fp, fn = (sum(row[i] for row in counts) for i in range(3))
        precision, recall, f1 = divide(tp, tp + fp), divide(tp, tp + fn), divide(2 * tp, 2 * tp + fp + fn)
    else:
        per_class = [
            (divide(tp, tp + fp), divide(tp, tp + fn), divide(2 * tp, 2 * tp + fp + fn))
            for tp, fp, fn, _ in counts
        ]
        weights = [1.0] * len(counts) if average == "macro" else [row[3] for row in counts]
        total = sum(weights)
        precision, recall, f1 = (
            divide(sum(w * values[i] for w, values in zip(weights, per_class)), total)
            for i in range(3)
        )
    return {"precision": float(precision), "recall": float(recall), "f1": float(f1)}

def qk_norm(q, k, eps=1e-6):
    def normalize(x):
        work = x.float() if x.dtype in (torch.float16, torch.bfloat16) else x
        inverse_rms = torch.rsqrt(work.square().mean(dim=-1, keepdim=True) + eps)
        return (work * inverse_rms).to(x.dtype)

    return normalize(q), normalize(k)

def reinforce_policy_loss(log_probs, returns, baseline, mask):
    import torch
    tensors = (log_probs, returns, baseline, mask)
    if (any(x.ndim != 1 for x in tensors)
            or any(x.shape != log_probs.shape or x.device != log_probs.device for x in tensors)
            or any(not x.is_floating_point() or not torch.isfinite(x).all()
                   for x in (log_probs, returns, baseline))
            or mask.dtype != torch.bool or not bool(mask.any())):
        raise ValueError("invalid policy-gradient inputs")
    advantage = returns.detach() - baseline.detach()
    return -(log_probs * advantage * mask).sum() / mask.sum()

from collections import Counter

def rl_data_audit(train, eval_rows):
    def inspect(rows):
        missing = []
        ids = []
        for index, row in enumerate(rows):
            if any(not isinstance(row.get(key), str) or not row.get(key) for key in ("sample_id", "prompt", "response")):
                missing.append(index)
            sample_id = row.get("sample_id")
            if isinstance(sample_id, str) and sample_id:
                ids.append(sample_id)
        return missing, Counter(ids)

    missing_train, train_ids = inspect(train)
    missing_eval, eval_ids = inspect(eval_rows)
    all_ids = train_ids.keys() | eval_ids.keys()
    return {
        "missing_train": missing_train,
        "missing_eval": missing_eval,
        "duplicate_ids": sorted(key for key in all_ids if train_ids[key] > 1 or eval_ids[key] > 1),
        "leakage_ids": sorted(train_ids.keys() & eval_ids.keys()),
    }

def rms_norm(x, weight, eps=1e-6):
    rms = torch.sqrt(x.pow(2).mean(dim=-1, keepdim=True) + eps)
    return x / rms * weight

import torch

def roc_auc(scores, labels):
    if scores.ndim != 1 or labels.ndim != 1 or scores.shape != labels.shape:
        raise ValueError("scores and labels must be 1-D tensors of equal length")
    labels = labels.long()
    if bool(((labels != 0) & (labels != 1)).any()):
        raise ValueError("labels must be 0 or 1")
    if not bool(torch.isfinite(scores).all()):
        raise ValueError("scores must be finite")
    n_pos = int(labels.sum())
    n_neg = labels.numel() - n_pos
    if n_pos == 0 or n_neg == 0:
        raise ValueError("AUC needs at least one positive and one negative")

    sorted_scores, order = torch.sort(scores.double())
    _, counts = torch.unique_consecutive(sorted_scores, return_counts=True)
    ends = torch.cumsum(counts, 0)
    average_rank = (ends - counts + 1 + ends).double() / 2
    ranks = torch.repeat_interleave(average_rank, counts)
    rank_sum = float(ranks[labels[order] == 1].sum())
    return (rank_sum - n_pos * (n_pos + 1) / 2) / (n_pos * n_neg)

def apply_rope(q, k):
    B, S, D = q.shape
    pos = torch.arange(S, device=q.device).unsqueeze(1).float()
    dim = torch.arange(0, D, 2, device=q.device).float()
    freqs = 1.0 / (10000.0 ** (dim / D))
    angles = pos * freqs
    cos_a = torch.cos(angles)
    sin_a = torch.sin(angles)

    def rotate(x):
        x1, x2 = x[..., 0::2], x[..., 1::2]
        return torch.stack([x1 * cos_a - x2 * sin_a,
                            x1 * sin_a + x2 * cos_a], dim=-1).flatten(-2)

    return rotate(q), rotate(k)

import torch

class SGDMomentum:
    def __init__(self, params, lr, momentum=0.0, weight_decay=0.0, nesterov=False):
        if lr < 0 or momentum < 0 or weight_decay < 0:
            raise ValueError("lr, momentum and weight_decay must be non-negative")
        if nesterov and momentum == 0:
            raise ValueError("Nesterov momentum requires momentum > 0")
        self.params = list(params)
        self.lr = lr
        self.momentum = momentum
        self.weight_decay = weight_decay
        self.nesterov = nesterov
        self.buffers = {}

    @torch.no_grad()
    def step(self):
        for index, p in enumerate(self.params):
            if p.grad is None:
                continue
            d = p.grad
            if self.weight_decay:
                d = d + self.weight_decay * p
            if self.momentum:
                buf = self.buffers.get(index)
                if buf is None:
                    buf = d.clone()
                    self.buffers[index] = buf
                else:
                    buf.mul_(self.momentum).add_(d)
                d = d + self.momentum * buf if self.nesterov else buf
            p.add_(d, alpha=-self.lr)

    def zero_grad(self):
        for p in self.params:
            p.grad = None

import torch
import torch.nn.functional as F

def preference_loss(chosen_logps, rejected_logps, loss_type, beta, chosen_lengths=None, rejected_lengths=None,
                    gamma=0.0, ref_chosen_logps=None, ref_rejected_logps=None):
    if beta <= 0:
        raise ValueError("beta must be positive")
    if loss_type == "simpo":
        if chosen_lengths is None or rejected_lengths is None:
            raise ValueError("SimPO needs response lengths")
        if bool((chosen_lengths <= 0).any()) or bool((rejected_lengths <= 0).any()):
            raise ValueError("lengths must be positive")
        margin = beta * (chosen_logps / chosen_lengths - rejected_logps / rejected_lengths) - gamma
        return F.softplus(-margin).mean()
    if loss_type == "ipo":
        if ref_chosen_logps is None or ref_rejected_logps is None:
            raise ValueError("IPO needs reference log-probabilities")
        gap = (chosen_logps - ref_chosen_logps) - (rejected_logps - ref_rejected_logps)
        return ((gap - 1 / (2 * beta)) ** 2).mean()
    raise ValueError(f"unknown loss_type {loss_type!r}")

class ToolRegistry:
    _TYPE_NAMES = {
        str: "string", int: "integer", float: "number",
        bool: "boolean", list: "array", dict: "object",
    }

    def __init__(self):
        self._tools = {}

    def register(self, tool):
        if not isinstance(tool.name, str) or not tool.name:
            raise ValueError("tool name must be non-empty")
        if tool.name in self._tools:
            raise ValueError(f"duplicate tool: {tool.name}")
        if not isinstance(tool.description, str) or not tool.description:
            raise ValueError("tool description must be non-empty")
        if not isinstance(tool.argument_schema, dict):
            raise TypeError("argument schema must be a dictionary")
        if any(not isinstance(name, str) or declared not in self._TYPE_NAMES
               for name, declared in tool.argument_schema.items()):
            raise TypeError("argument schema contains an unsupported entry")
        self._tools[tool.name] = tool

    def describe(self):
        return [
            {
                "name": tool.name,
                "description": tool.description,
                "parameters": {
                    name: self._TYPE_NAMES[declared]
                    for name, declared in tool.argument_schema.items()
                },
            }
            for tool in self._tools.values()
        ]

    def invoke(self, name, arguments, idempotency_key=None):
        if name not in self._tools:
            raise KeyError(f"unknown tool: {name}")
        if not isinstance(arguments, dict):
            raise TypeError("arguments must be a dictionary")
        tool = self._tools[name]
        if set(arguments) != set(tool.argument_schema):
            raise ValueError("argument names do not match the schema")
        for argument, declared in tool.argument_schema.items():
            if type(arguments[argument]) is not declared:
                raise TypeError(f"invalid type for {argument}")
        return tool.invoke(arguments, idempotency_key=idempotency_key)

import math
import torch

def truncated_is_weights(train_logprobs, rollout_logprobs, mask, cap=2.0, level="token"):
    if cap <= 0:
        raise ValueError("cap must be positive")
    if level not in ("token", "sequence"):
        raise ValueError(f"unknown level {level!r}")
    if train_logprobs.ndim != 2 or train_logprobs.shape != rollout_logprobs.shape or train_logprobs.shape != mask.shape:
        raise ValueError("inputs must share one (B, T) shape")
    mask = mask.bool()
    delta = torch.where(mask, train_logprobs.detach() - rollout_logprobs.detach(), torch.zeros_like(train_logprobs))
    if level == "sequence":
        delta = delta.sum(dim=1, keepdim=True).expand_as(delta)
    weights = torch.exp(torch.clamp(delta, max=math.log(cap)))
    return torch.where(mask, weights, torch.zeros_like(weights))

class PatchEmbedding(nn.Module):
    def __init__(self, img_size, patch_size, in_channels, embed_dim):
        super().__init__()
        self.patch_size = patch_size
        self.num_patches = (img_size // patch_size) ** 2
        self.proj = nn.Linear(in_channels * patch_size * patch_size, embed_dim)

    def forward(self, x):
        B, C, H, W = x.shape
        p = self.patch_size
        n_h, n_w = H // p, W // p
        x = x.reshape(B, C, n_h, p, n_w, p)
        x = x.permute(0, 2, 4, 1, 3, 5).reshape(B, n_h * n_w, C * p * p)
        return self.proj(x)

def finalize_agent_rollout(response_ids, response_mask, rollout_log_probs, reward, max_response_length, overlong_penalty):
    import math
    import torch

    tensors = (response_ids, response_mask, rollout_log_probs)
    if any(not isinstance(tensor, torch.Tensor) or tensor.ndim != 1 for tensor in tensors):
        raise ValueError("response tensors must be one-dimensional tensors")
    if response_ids.numel() == 0:
        raise ValueError("response tensors must be non-empty")
    if not (response_ids.numel() == response_mask.numel() == rollout_log_probs.numel()):
        raise ValueError("response tensors must have the same length")
    if not (response_ids.device == response_mask.device == rollout_log_probs.device):
        raise ValueError("response tensors must be on the same device")
    if response_ids.dtype == torch.bool or torch.is_floating_point(response_ids) or torch.is_complex(response_ids):
        raise ValueError("response_ids must use an integer dtype")
    if response_mask.dtype != torch.bool:
        raise ValueError("response_mask must use boolean dtype")
    if not rollout_log_probs.dtype.is_floating_point:
        raise ValueError("rollout_log_probs must use a floating-point dtype")
    if not isinstance(max_response_length, int) or isinstance(max_response_length, bool) or max_response_length < 1:
        raise ValueError("max_response_length must be a positive integer")
    penalty = float(overlong_penalty)
    if math.isnan(penalty) or penalty < 0:
        raise ValueError("overlong_penalty must be non-negative")

    original_length = response_ids.numel()
    truncated = original_length > max_response_length
    kept = min(original_length, max_response_length)
    kept_ids = response_ids[:kept].clone()
    kept_mask = response_mask[:kept].clone()
    kept_log_probs = rollout_log_probs[:kept].clone()

    effective_reward = float(reward) - (penalty if truncated else 0.0)
    token_rewards = torch.zeros_like(kept_log_probs)
    token_rewards[-1] = effective_reward

    return {
        "response_ids": kept_ids,
        "response_mask": kept_mask,
        "rollout_log_probs": kept_log_probs,
        "token_rewards": token_rewards,
        "truncated": truncated,
    }

class ApprovalRequest:
    def __init__(self, digest, action, identity, expires_at):
        from copy import deepcopy
        self.digest = digest
        self.action = deepcopy(action)
        self.identity = identity
        self.expires_at = expires_at


class ApprovedAction:
    def __init__(self, action):
        from copy import deepcopy
        self.action = deepcopy(action)


class DeniedAction:
    def __init__(self, reason):
        self.reason = reason


class ApprovalGate:
    def __init__(self, approval_required, clock, ttl=60):
        from math import isfinite
        if not isinstance(approval_required, set) or not all(
            isinstance(item, str) and item for item in approval_required
        ):
            raise TypeError("approval_required must be a set of capability strings")
        if (isinstance(ttl, bool) or not isinstance(ttl, (int, float))
                or not isfinite(float(ttl)) or ttl <= 0):
            raise ValueError("ttl must be a positive finite number")
        self._approval_required = frozenset(approval_required)
        self._clock = clock
        self._ttl = float(ttl)
        self._requests = {}
        self._grants = {}
        self._sequence = 0

    def _validated(self, action, capabilities, provenance):
        from copy import deepcopy
        from torch_judge.harness.agents.protocol import copy_json
        try:
            copied = copy_json(action, field="approval action JSON")
            source = copy_json(provenance, field="approval provenance JSON")
        except Exception:
            return DeniedAction("malformed_request")
        if not isinstance(copied, dict) or not isinstance(source, dict):
            return DeniedAction("malformed_request")
        if not isinstance(capabilities, set) or not all(
            isinstance(item, str) and item for item in capabilities
        ):
            return DeniedAction("malformed_capabilities")
        required = ("tool", "capability", "actor", "arguments")
        if (any(not isinstance(copied.get(key), str) or not copied[key]
                for key in required[:3]) or not isinstance(copied.get("arguments"), dict)):
            return DeniedAction("malformed_request")
        if (not isinstance(source.get("identity"), str) or not source["identity"]
                or not isinstance(source.get("source"), str) or not source["source"]
                or source.get("trust") not in {"trusted", "untrusted"}):
            return DeniedAction("malformed_provenance")
        if source["identity"] != copied["actor"]:
            return DeniedAction("identity_mismatch")
        if copied["capability"] not in capabilities:
            return DeniedAction("capability_not_granted")
        return deepcopy(copied), deepcopy(source)

    @staticmethod
    def _digest(action, provenance):
        import hashlib
        import json
        bound_action = {key: value for key, value in action.items() if key != "approval_token"}
        bound = {
            "action": bound_action,
            "identity": provenance["identity"],
            "source": provenance["source"],
        }
        encoded = json.dumps(bound, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(encoded.encode("utf-8")).hexdigest()

    def classify(self, action, capabilities, provenance):
        checked = self._validated(action, capabilities, provenance)
        if isinstance(checked, DeniedAction):
            return checked
        copied, source = checked
        capability = copied["capability"]
        clean_action = {key: value for key, value in copied.items() if key != "approval_token"}
        if capability not in self._approval_required:
            return ApprovedAction(clean_action)
        if source["trust"] != "trusted":
            return DeniedAction("untrusted_provenance")
        digest = self._digest(copied, source)
        token = copied.get("approval_token")
        if token is None:
            request = ApprovalRequest(
                digest, clean_action, source["identity"], self._clock.now() + self._ttl
            )
            self._requests[id(request)] = {
                "digest": digest,
                "identity": source["identity"],
                "expires_at": request.expires_at,
                "approved": False,
            }
            return request
        grant = self._grants.get(token) if isinstance(token, str) else None
        if grant is None:
            return DeniedAction("approval_invalid")
        if grant["consumed"]:
            return DeniedAction("approval_replayed")
        if grant["digest"] != digest or grant["identity"] != source["identity"]:
            return DeniedAction("approval_mismatch")
        if self._clock.now() >= grant["expires_at"]:
            return DeniedAction("approval_expired")
        grant["consumed"] = True
        return ApprovedAction(clean_action)

    def approve(self, request, approver):
        import hashlib
        if not isinstance(request, ApprovalRequest) or id(request) not in self._requests:
            raise TypeError("request must originate from this gate")
        if (not isinstance(approver, dict)
                or not isinstance(approver.get("identity"), str) or not approver["identity"]
                or approver.get("trust") != "trusted"):
            raise ValueError("approver must be a trusted named identity")
        stored = self._requests[id(request)]
        if stored["approved"]:
            raise ValueError("approval request was already approved")
        stored["approved"] = True
        self._sequence += 1
        token = hashlib.sha256(
            f"{stored['digest']}:{approver['identity']}:{self._sequence}".encode("utf-8")
        ).hexdigest()
        self._grants[token] = {
            "digest": stored["digest"],
            "identity": stored["identity"],
            "expires_at": stored["expires_at"],
            "consumed": False,
        }
        return token

async def async_agent_rollout(rollout_fn, items, max_concurrency, timeout):
    import asyncio
    if not isinstance(max_concurrency, int) or isinstance(max_concurrency, bool) or max_concurrency <= 0:
        raise ValueError("max_concurrency must be positive")
    if timeout <= 0:
        raise ValueError("timeout must be positive")

    async def run_one(index, item, semaphore):
        async with semaphore:
            try:
                value = await asyncio.wait_for(rollout_fn(item), timeout=timeout)
            except asyncio.TimeoutError:
                return index, {"item": item, "status": "timeout", "value": None}
            except Exception:
                return index, {"item": item, "status": "error", "value": None}
            return index, {"item": item, "status": "ok", "value": value}

    async def run_all():
        semaphore = asyncio.Semaphore(max_concurrency)
        results = await asyncio.gather(
            *(run_one(index, item, semaphore) for index, item in enumerate(items))
        )
        return [entry for _, entry in sorted(results)]

    return await run_all()

class SimpleBPE:
    def __init__(self):
        self.merges = []

    def train(self, corpus, num_merges):
        vocab = {}
        for word in corpus:
            symbols = tuple(word) + ('</w>',)
            vocab[symbols] = vocab.get(symbols, 0) + 1
        self.merges = []
        for _ in range(num_merges):
            pairs = {}
            for word, freq in vocab.items():
                for i in range(len(word) - 1):
                    pair = (word[i], word[i + 1])
                    pairs[pair] = pairs.get(pair, 0) + freq
            if not pairs:
                break
            best = max(pairs, key=pairs.get)
            self.merges.append(best)
            new_vocab = {}
            for word, freq in vocab.items():
                new_word = []
                i = 0
                while i < len(word):
                    if i < len(word) - 1 and (word[i], word[i + 1]) == best:
                        new_word.append(word[i] + word[i + 1])
                        i += 2
                    else:
                        new_word.append(word[i])
                        i += 1
                new_vocab[tuple(new_word)] = freq
            vocab = new_vocab

    def encode(self, text):
        all_tokens = []
        for word in text.split():
            symbols = list(word) + ['</w>']
            for a, b in self.merges:
                i = 0
                while i < len(symbols) - 1:
                    if symbols[i] == a and symbols[i + 1] == b:
                        symbols = symbols[:i] + [a + b] + symbols[i + 2:]
                    else:
                        i += 1
            all_tokens.extend(symbols)
        return all_tokens

def budgeted_agent_loop(model, registry, messages, limits, retry_policy, clock, trace):
    from copy import deepcopy
    from math import isfinite
    from torch_judge.harness import HarnessFailure
    from torch_judge.harness.agents import (AgentResult, PermanentModelError,
        PermanentToolError, RetryableModelError, RetryableToolError)
    from torch_judge.harness.agents.protocol import copy_json

    run_id = correlation_id = "agent-run"
    start = clock.now()
    state = deepcopy(messages)
    iterations = tool_calls = tokens = 0
    cost = 0.0

    required = ("max_iterations", "max_tool_calls", "max_tokens", "max_time", "max_cost")
    if any(name not in limits for name in required):
        raise ValueError("limits are incomplete")
    if any(isinstance(limits[name], bool) or not isinstance(limits[name], (int, float))
           or not isfinite(float(limits[name])) or limits[name] < 0 for name in required):
        raise ValueError("limits must be non-negative finite numbers")
    max_attempts = retry_policy.get("max_attempts")
    base_delay = retry_policy.get("base_delay")
    if not isinstance(max_attempts, int) or isinstance(max_attempts, bool) or max_attempts < 1:
        raise ValueError("max_attempts must be a positive integer")
    if isinstance(base_delay, bool) or not isinstance(base_delay, (int, float)) or base_delay < 0:
        raise ValueError("base_delay must be non-negative")

    def elapsed():
        return clock.now() - start

    def cancelled():
        value = limits.get("cancelled", False)
        return bool(value() if callable(value) else value)

    terminal_events = {
        "completed": "run.completed", "failed": "run.failed",
        "budget_exceeded": "run.budget_exceeded", "cancelled": "run.cancelled",
    }

    def finish(status, content=None, failure=None):
        trace.emit(terminal_events[status], clock.now(), run_id, correlation_id,
                   {} if failure is None else {"failure": failure})
        return AgentResult(status, content, state, iterations, tool_calls, tokens,
                           cost, elapsed(), failure)

    def budget_failure(limit):
        return finish("budget_exceeded", failure={"type": "budget", "limit": limit})

    trace.emit("run.started", clock.now(), run_id, correlation_id, {})
    while True:
        if cancelled():
            return finish("cancelled", failure={"type": "cancelled"})
        if elapsed() > limits["max_time"]:
            return budget_failure("time")
        if iterations >= limits["max_iterations"]:
            return budget_failure("iterations")

        for model_attempt in range(1, max_attempts + 1):
            if cancelled():
                return finish("cancelled", failure={"type": "cancelled"})
            if elapsed() > limits["max_time"]:
                return budget_failure("time")
            if iterations >= limits["max_iterations"]:
                return budget_failure("iterations")
            iterations += 1
            try:
                response = model.call(deepcopy(state))
                trace.emit("model.called", clock.now(), run_id, correlation_id,
                           {"iteration": iterations, "attempt": model_attempt})
                break
            except HarnessFailure:
                raise
            except PermanentModelError as error:
                trace.emit("model.failed", clock.now(), run_id, correlation_id,
                           {"attempt": model_attempt, "type": "permanent"})
                return finish("failed", failure={"type": "permanent_model_failure",
                                                  "message": str(error)})
            except (RetryableModelError, TimeoutError) as error:
                trace.emit("model.failed", clock.now(), run_id, correlation_id,
                           {"attempt": model_attempt, "type": "retryable"})
                if model_attempt == max_attempts:
                    return finish("failed", failure={"type": "model_retry_exhausted",
                                                      "attempts": model_attempt,
                                                      "message": str(error)})
                delay = (error.retry_after if isinstance(error, RetryableModelError)
                         and error.retry_after is not None
                         else base_delay * 2 ** (model_attempt - 1))
                if elapsed() + delay > limits["max_time"]:
                    return budget_failure("time")
                trace.emit("model.retry", clock.now(), run_id, correlation_id,
                           {"attempt": model_attempt, "delay": delay})
                clock.sleep(delay)
            except Exception as error:
                trace.emit("model.failed", clock.now(), run_id, correlation_id,
                           {"attempt": model_attempt, "type": "unexpected",
                            "error_type": type(error).__name__})
                return finish("failed", failure={"type": "model_execution_failure",
                                                  "error_type": type(error).__name__,
                                                  "message": str(error)})
        try:
            if not isinstance(response, dict):
                raise ValueError
            usage = response.get("usage")
            used_tokens = usage.get("tokens") if isinstance(usage, dict) else None
            used_cost = usage.get("cost") if isinstance(usage, dict) else None
            if (not isinstance(used_tokens, int) or isinstance(used_tokens, bool)
                    or used_tokens < 0):
                raise ValueError
            if (not isinstance(used_cost, (int, float)) or isinstance(used_cost, bool)
                    or not isfinite(float(used_cost)) or used_cost < 0):
                raise ValueError
        except (AttributeError, ValueError):
            return finish("failed", failure={"type": "malformed_model_response"})
        tokens += used_tokens
        cost += float(used_cost)
        if tokens > limits["max_tokens"]:
            return budget_failure("tokens")
        if cost > limits["max_cost"]:
            return budget_failure("cost")
        if elapsed() > limits["max_time"]:
            return budget_failure("time")

        response_type = response.get("type")
        if response_type == "final":
            if not isinstance(response.get("content"), str):
                return finish("failed", failure={"type": "malformed_model_response"})
            return finish("completed", content=response["content"])
        if response_type != "tool_call":
            return finish("failed", failure={"type": "malformed_model_response"})
        call_id = response.get("call_id")
        name = response.get("name")
        arguments = response.get("arguments")
        idempotency_key = response.get("idempotency_key", None)
        if (not isinstance(call_id, str) or not call_id
                or not isinstance(name, str) or not name
                or not isinstance(arguments, dict)
                or (idempotency_key is not None
                    and (not isinstance(idempotency_key, str) or not idempotency_key))):
            return finish("failed", failure={"type": "malformed_model_response"})
        idempotency_key = idempotency_key or call_id

        for attempt in range(1, max_attempts + 1):
            if cancelled():
                return finish("cancelled", failure={"type": "cancelled"})
            if tool_calls >= limits["max_tool_calls"]:
                return budget_failure("tool_calls")
            if elapsed() > limits["max_time"]:
                return budget_failure("time")
            tool_calls += 1
            trace.emit("tool.started", clock.now(), run_id, correlation_id,
                       {"tool": name, "call_id": call_id, "attempt": attempt})
            try:
                tool_result = registry.invoke(name, deepcopy(arguments), idempotency_key)
                try:
                    tool_result = copy_json(tool_result, field="tool result JSON")
                except Exception:
                    trace.emit("tool.failed", clock.now(), run_id, correlation_id,
                               {"tool": name, "type": "malformed_tool_result"})
                    return finish("failed", failure={"type": "malformed_tool_result", "tool": name})
                state.append({"role": "tool", "tool_call_id": call_id,
                              "name": name, "content": tool_result})
                trace.emit("tool.completed", clock.now(), run_id, correlation_id,
                           {"tool": name, "call_id": call_id, "attempt": attempt})
                break
            except HarnessFailure:
                raise
            except PermanentToolError as error:
                trace.emit("tool.failed", clock.now(), run_id, correlation_id,
                           {"tool": name, "type": "permanent", "attempt": attempt})
                return finish("failed", failure={"type": "permanent_tool_failure",
                                                  "tool": name, "message": str(error)})
            except RetryableToolError as error:
                if attempt == max_attempts:
                    trace.emit("tool.failed", clock.now(), run_id, correlation_id,
                               {"tool": name, "type": "retry_exhausted", "attempt": attempt})
                    return finish("failed", failure={"type": "retry_exhausted", "tool": name,
                                                      "attempts": attempt, "message": str(error)})
                delay = error.retry_after if error.retry_after is not None else base_delay * 2 ** (attempt - 1)
                if elapsed() + delay > limits["max_time"]:
                    return budget_failure("time")
                trace.emit("tool.retry", clock.now(), run_id, correlation_id,
                           {"tool": name, "call_id": call_id, "attempt": attempt, "delay": delay})
                clock.sleep(delay)
            except Exception as error:
                trace.emit("tool.failed", clock.now(), run_id, correlation_id,
                           {"tool": name, "type": "unexpected", "attempt": attempt,
                            "error_type": type(error).__name__})
                return finish("failed", failure={"type": "tool_execution_failure",
                                                  "tool": name,
                                                  "error_type": type(error).__name__,
                                                  "message": str(error)})

import torch
import torch.nn.functional as F
from torch.utils.checkpoint import checkpoint

def chunked_cross_entropy(hidden, weight, targets, chunk_size, ignore_index=-100):
    if chunk_size < 1:
        raise ValueError("chunk_size must be positive")
    if hidden.ndim != 2 or weight.ndim != 2 or hidden.shape[1] != weight.shape[1] or targets.shape != hidden.shape[:1]:
        raise ValueError("expected hidden (N, D), weight (V, D) and targets (N,)")
    valid = int((targets != ignore_index).sum())
    if valid == 0:
        raise ValueError("no target to score")

    def chunk_loss(h, w, t):
        return F.cross_entropy(h @ w.T, t, ignore_index=ignore_index, reduction="sum")

    total = hidden.new_zeros(())
    for start in range(0, hidden.shape[0], chunk_size):
        end = start + chunk_size
        total = total + checkpoint(chunk_loss, hidden[start:end], weight, targets[start:end], use_reentrant=False)
    return total / valid

def compact_context(messages, token_budget, summary_budget, count_tokens, summarize):
    if not isinstance(messages, list):
        raise ValueError("messages must be a list")
    for message in messages:
        if not isinstance(message, dict):
            raise ValueError("every message must be a dictionary")
        role = message.get("role")
        if not isinstance(role, str) or not role:
            raise ValueError("every message needs a non-empty string role")
    for name, value in (("token_budget", token_budget), ("summary_budget", summary_budget)):
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ValueError(f"{name} must be a non-negative integer")
    if summary_budget > token_budget:
        raise ValueError("summary_budget cannot exceed token_budget")

    pinned = messages[:1] if messages and messages[0]["role"] == "system" else []

    blocks = []
    for message in messages[len(pinned):]:
        if message["role"] == "tool":
            if not blocks or not blocks[-1][0].get("tool_calls"):
                raise ValueError("a tool message must follow the assistant turn that called it")
            blocks[-1].append(message)
        else:
            blocks.append([message])

    pinned_tokens = sum(count_tokens(message) for message in pinned)
    if pinned_tokens > token_budget:
        raise ValueError("the pinned system message alone exceeds token_budget")

    block_tokens = [sum(count_tokens(message) for message in block) for block in blocks]
    total = pinned_tokens + sum(block_tokens)
    if total <= token_budget:
        return {
            "messages": [dict(message) for message in messages],
            "dropped": 0,
            "compacted": False,
            "tokens": total,
        }

    if pinned_tokens + summary_budget > token_budget:
        raise ValueError("no room for the summary inside token_budget")
    available = token_budget - pinned_tokens - summary_budget

    start = len(blocks)
    used = 0
    for index in range(len(blocks) - 1, -1, -1):
        if used + block_tokens[index] > available:
            break
        used += block_tokens[index]
        start = index

    dropped = [message for block in blocks[:start] for message in block]
    text = summarize(dropped)
    if not isinstance(text, str) or not text.strip():
        raise ValueError("summarize must return a non-empty string")
    summary = {"role": "system", "content": text, "compacted": True}
    summary_tokens = count_tokens(summary)
    if summary_tokens > summary_budget:
        raise ValueError("the summary exceeded summary_budget")

    kept = [dict(message) for block in blocks[start:] for message in block]
    return {
        "messages": [dict(message) for message in pinned] + [summary] + kept,
        "dropped": len(dropped),
        "compacted": True,
        "tokens": pinned_tokens + summary_tokens + used,
    }

def _chain(middleware, args, inner):
    queue = list(middleware)

    def next():
        if queue:
            return queue.pop(0)(*args, next)
        return inner()

    return next()


def _error(message, code=None):
    return {"is_error": True, "content": [{"type": "text", "text": f"Error: {message}"}],
            "error": {"message": message, "code": code}}


class ToolRuntime:
    def __init__(self, tools, approve=None):
        self.tools = tools
        self.approve = approve
        self.pre_execute = []
        self.guards = []
        self.around = []
        self.post_execute = []
        self.observers = []

    def _body(self, call):
        name = call["name"]
        if name not in self.tools:
            return _error(f'unknown tool "{name}"', "UNKNOWN_TOOL")
        try:
            return {"is_error": False, "content": self.tools[name](call["arguments"])}
        except Exception as error:
            return _error(str(error))

    def _resolve_ask(self, call, decision):
        name = call["name"]
        if self.approve is None:
            return {"kind": "deny", "reason": decision.get("reason") or f'tool "{name}" requires approval (not yet supported)'}
        outcome = self.approve(call, decision.get("reason"))
        if outcome == "allowed-once":
            return {"kind": "allow"}
        if outcome == "rejected":
            return {"kind": "deny", "reason": f'the user rejected tool "{name}"'}
        return {"kind": "deny", "reason": f'approval for tool "{name}" was cancelled'}

    def _post(self, call, result):
        decision = _chain(self.post_execute, (call, result), lambda: {"kind": "accept"})
        extra = list(decision.get("additional_contexts") or [])
        if decision["kind"] == "block":
            feedback = decision["feedback"]
            text = "\n".join(b["text"] for b in feedback if b.get("type") == "text")
            blocked = {"is_error": True, "content": feedback, "error": {"message": text, "code": None}}
            if extra:
                blocked["additional_contexts"] = extra
            return blocked
        accepted = dict(result)
        if "content" in decision:
            accepted["content"] = decision["content"]
        contexts = list(result.get("additional_contexts") or []) + extra
        if contexts:
            accepted["additional_contexts"] = contexts
        return accepted

    def _run(self, call):
        decision = _chain(self.pre_execute, (call,), lambda: {"kind": "allow"})
        if decision["kind"] == "ask":
            decision = self._resolve_ask(call, decision)
        if decision["kind"] == "cancel":
            result = _error("tool call aborted before dispatch", "ABORTED_BEFORE_DISPATCH")
        else:
            reason = decision.get("reason") if decision["kind"] == "deny" else None
            if decision["kind"] == "allow":
                for guard in self.guards:
                    reason = guard(call)
                    if reason is not None:
                        break
            if reason is not None:
                result = _error(reason)
            else:
                result = _chain(self.around, (call,), lambda: self._body(call))
        return self._post(call, result)

    def execute(self, call):
        try:
            result = self._run(call)
        except Exception as error:
            result = _error(str(error))
        for observer in self.observers:
            try:
                observer(call, result)
            except Exception:
                pass
        return result

import asyncio
from types import SimpleNamespace


class _Signal:
    def __init__(self):
        self.aborted = False
        self.reason = None
        self._listeners = []

    def add_listener(self, fn):
        if self.aborted:
            fn(self.reason)
        else:
            self._listeners.append(fn)


class AbortController:
    def __init__(self):
        self.signal = _Signal()

    def abort(self, reason):
        signal = self.signal
        if signal.aborted:
            return
        signal.aborted = True
        signal.reason = reason
        listeners, signal._listeners = signal._listeners, []
        for fn in listeners:
            fn(reason)


def any_signal(signals):
    controller = AbortController()
    for signal in signals:
        if signal.aborted:
            controller.abort(signal.reason)
            return controller.signal
    for signal in signals:
        signal.add_listener(controller.abort)
    return controller.signal


class TimeoutReason(Exception):
    def __init__(self, code, timeout):
        super().__init__(f"{code} after {timeout}s")
        self.code = code
        self.timeout = timeout


class _Deadline:
    def __init__(self, signal, handle=None):
        self.signal = signal
        self._handle = handle

    def dispose(self):
        if self._handle is not None:
            self._handle.cancel()


def deadline(upstream, timeout, code):
    if timeout <= 0:
        return _Deadline(upstream if upstream is not None else AbortController().signal)
    timer = AbortController()
    handle = asyncio.get_running_loop().call_later(timeout, timer.abort, TimeoutReason(code, timeout))
    signal = timer.signal if upstream is None else any_signal([upstream, timer.signal])
    return _Deadline(signal, handle)


def timeout_of(signal, code=None):
    reason = signal.reason
    if not isinstance(reason, TimeoutReason):
        return None
    return reason if code is None or reason.code == code else None


async def with_timeout(execution, next, timeout):
    if timeout is None:
        return await next()
    d = deadline(execution["signal"], timeout, "TOOL_TIMEOUT")
    upstream = execution["signal"]
    execution["signal"] = d.signal
    try:
        result = await next()
        if timeout_of(d.signal, "TOOL_TIMEOUT") is not None:
            message = f"tool call timed out after {timeout}s"
            return {"is_error": True, "content": [{"type": "text", "text": f"Error: {message}"}],
                    "error": {"message": message, "code": "TOOL_TIMEOUT"}}
        return result
    finally:
        execution["signal"] = upstream
        d.dispose()


tool_timeout = SimpleNamespace(AbortController=AbortController, any_signal=any_signal, deadline=deadline,
                               timeout_of=timeout_of, TimeoutReason=TimeoutReason, with_timeout=with_timeout)

async def fully_async_rollout_buffer(rollout_fn, train_fn, items, max_concurrency, train_batch_size, timeout):
    import asyncio
    if not isinstance(max_concurrency, int) or isinstance(max_concurrency, bool) or max_concurrency <= 0:
        raise ValueError("max_concurrency must be positive")
    if not isinstance(train_batch_size, int) or isinstance(train_batch_size, bool) or train_batch_size <= 0:
        raise ValueError("train_batch_size must be positive")
    if timeout <= 0:
        raise ValueError("timeout must be positive")

    async def produce(index, item, semaphore):
        async with semaphore:
            try:
                value = await asyncio.wait_for(rollout_fn(item), timeout=timeout)
            except asyncio.TimeoutError:
                return index, {"item": item, "status": "timeout", "value": None}
            except Exception:
                return index, {"item": item, "status": "error", "value": None}
            return index, {"item": item, "status": "ok", "value": value}

    semaphore = asyncio.Semaphore(max_concurrency)
    tasks = [
        asyncio.create_task(produce(index, item, semaphore))
        for index, item in enumerate(items)
    ]
    buffer, failures, trained_batches = [], [], []

    async def emit_ready(force=False):
        while len(buffer) >= train_batch_size or (force and buffer):
            batch = sorted(buffer[:train_batch_size], key=lambda entry: entry[0])
            del buffer[:train_batch_size]
            public_batch = [entry[1] for entry in batch]
            await train_fn(public_batch)
            trained_batches.append(public_batch)

    for completed in asyncio.as_completed(tasks):
        index, result = await completed
        if result["status"] == "ok":
            buffer.append((index, result))
            await emit_ready()
        else:
            failures.append((index, result))

    await emit_ready(force=True)
    failures = [result for _, result in sorted(failures)]
    return {"trained_batches": trained_batches, "failures": failures}

import torch


def gae_advantage(rewards, values, dones, gamma=0.99, lam=0.95):
    if rewards.shape != dones.shape:
        raise ValueError(
            f"rewards {tuple(rewards.shape)} and dones {tuple(dones.shape)} must match"
        )
    horizon = rewards.shape[-1]
    if values.shape[:-1] != rewards.shape[:-1] or values.shape[-1] != horizon + 1:
        raise ValueError(
            f"values {tuple(values.shape)} must have exactly one more column than "
            f"rewards {tuple(rewards.shape)}"
        )
    if not 0.0 <= gamma <= 1.0:
        raise ValueError(f"gamma must lie in [0, 1], got {gamma}")
    if not 0.0 <= lam <= 1.0:
        raise ValueError(f"lam must lie in [0, 1], got {lam}")

    not_done = 1.0 - dones.to(rewards.dtype)
    deltas = rewards + gamma * values[..., 1:] * not_done - values[..., :-1]

    advantages = torch.zeros_like(rewards)
    running = torch.zeros_like(rewards[..., 0])
    for t in reversed(range(horizon)):
        running = deltas[..., t] + gamma * lam * not_done[..., t] * running
        advantages[..., t] = running
    return advantages

import torch


def grpo_token_loss(logprobs, ref_logprobs, advantages, mask, beta=0.04):
    if logprobs.shape != ref_logprobs.shape or logprobs.shape != mask.shape:
        raise ValueError(
            f"logprobs {tuple(logprobs.shape)}, ref_logprobs {tuple(ref_logprobs.shape)} "
            f"and mask {tuple(mask.shape)} must share a shape"
        )
    if advantages.shape != logprobs.shape[:1]:
        raise ValueError(
            f"advantages {tuple(advantages.shape)} must have one entry per row of "
            f"{tuple(logprobs.shape)}"
        )
    if beta < 0:
        raise ValueError(f"beta must be non-negative, got {beta}")

    keep = mask.to(logprobs.dtype)
    denominator = keep.sum()
    if denominator == 0:
        return torch.zeros((), dtype=logprobs.dtype, device=logprobs.device)

    log_ratio = ref_logprobs - logprobs
    kl = torch.exp(log_ratio) - log_ratio - 1.0
    objective = advantages.unsqueeze(-1) * logprobs - beta * kl
    return -(objective * keep).sum() / denominator

class GuardedResult:
    def __init__(self, status, output=None, failure=None, audit_records=None, pending_approval=None):
        from copy import deepcopy
        self.status = status
        self.output = deepcopy(output)
        self.failure = deepcopy(failure)
        self.audit_records = deepcopy(audit_records or [])
        self.pending_approval = pending_approval


def guarded_runtime(runtime, policy_engine, approval_gate, redactor, audit_sink, request):
    import hashlib
    import json
    from copy import deepcopy
    from math import isfinite
    from torch_judge.harness import HarnessFailure
    from torch_judge.harness.agents.protocol import copy_json

    class AuditFailure(Exception):
        def __init__(self, error): self.error = error

    class RedactionFailure(Exception):
        def __init__(self, error): self.error = error

    if not isinstance(request, dict):
        raise ValueError("request must be a dictionary")
    run_id = request.get("run_id")
    input_value = request.get("input")
    capabilities = request.get("capabilities")
    max_depth = request.get("max_delegation_depth")
    max_steps = request.get("max_steps")
    if not isinstance(run_id, str) or not run_id:
        raise ValueError("run_id must be non-empty")
    if not isinstance(capabilities, list) or not all(
        isinstance(item, str) and item for item in capabilities
    ) or len(capabilities) != len(set(capabilities)):
        raise ValueError("capabilities must be unique strings")
    if not isinstance(max_depth, int) or isinstance(max_depth, bool) or max_depth < 0:
        raise ValueError("max_delegation_depth must be a non-negative integer")
    if not isinstance(max_steps, int) or isinstance(max_steps, bool) or max_steps < 1:
        raise ValueError("max_steps must be a positive integer")

    def provenance(value):
        if (not isinstance(value, dict)
                or not isinstance(value.get("source"), str) or not value["source"]
                or value.get("trust") not in {"trusted", "untrusted"}):
            raise ValueError("provenance needs source and explicit trust")
        return copy_json(value, field="guardrail provenance JSON")

    if not isinstance(input_value, dict) or "content" not in input_value:
        raise ValueError("input needs content and provenance")
    initial = {
        "content": copy_json(input_value["content"], field="guarded input JSON"),
        "provenance": provenance(input_value.get("provenance")),
    }
    cancelled_value = request.get("cancelled", False)

    def cancelled():
        return bool(cancelled_value() if callable(cancelled_value) else cancelled_value)

    records = []
    previous_hash = "0" * 64

    def audit(event, data):
        nonlocal previous_hash
        try:
            sanitized = redactor.redact(copy_json(data, field="audit data JSON"))
            sanitized = copy_json(sanitized, field="redacted audit JSON")
        except HarnessFailure:
            raise
        except Exception as error:
            raise RedactionFailure(error) from error
        base = {
            "sequence": len(records),
            "event": event,
            "data": sanitized,
            "previous_hash": previous_hash,
        }
        canonical = json.dumps(base, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        record = {**base, "hash": hashlib.sha256(canonical.encode("utf-8")).hexdigest()}
        try:
            audit_sink.append(deepcopy(record))
        except HarnessFailure:
            raise
        except Exception as error:
            raise AuditFailure(error) from error
        records.append(record)
        previous_hash = record["hash"]

    def stop(status, failure=None, *, event=None, data=None, pending=None, output=None):
        if event is not None:
            audit(event, {} if data is None else data)
        return GuardedResult(status, output, failure, records, pending)

    def cancel_runtime():
        runtime.cancel()

    def safe_error_message(error):
        try:
            value = redactor.redact(str(error))
            return value if isinstance(value, str) else "[REDACTED ERROR]"
        except HarnessFailure:
            raise
        except Exception:
            return "[REDACTED ERROR]"

    def apply_policy(context):
        original_provenance = deepcopy(context["provenance"])
        original_kind = context["kind"]
        decision = policy_engine.evaluate(deepcopy(context))
        if getattr(decision, "action", None) not in {"allow", "deny", "transform"}:
            return None, {"type": "policy_failure", "reason": "invalid_decision"}
        if decision.action == "deny":
            return None, {"type": "policy_denied", "reasons": list(decision.reasons)}
        result = deepcopy(decision.context)
        if not isinstance(result, dict):
            return None, {"type": "policy_failure", "reason": "invalid_context"}
        result["kind"] = original_kind
        result["provenance"] = original_provenance
        return result, None

    try:
        if cancelled():
            cancel_runtime()
            return stop("cancelled", {"type": "cancelled"}, event="run.cancelled")
        input_context, failure = apply_policy({
            "kind": "request_input", "content": initial["content"],
            "provenance": initial["provenance"], "delegation_depth": 0,
        })
        if failure:
            cancel_runtime()
            return stop("denied", failure, event="policy.denied", data=failure)
        runtime_input = {
            "content": deepcopy(input_context.get("content")),
            "provenance": deepcopy(initial["provenance"]),
        }
        audit("request.accepted", input_context)
        output = None
        steps = 0
        for raw_event in runtime.events(deepcopy(runtime_input)):
            if cancelled():
                cancel_runtime()
                return stop("cancelled", {"type": "cancelled"}, event="run.cancelled")
            steps += 1
            if steps > max_steps:
                cancel_runtime()
                failure = {"type": "step_budget", "max_steps": max_steps}
                return stop("denied", failure, event="budget.denied", data=failure)
            event = copy_json(raw_event, field="runtime event JSON")
            if not isinstance(event, dict) or event.get("kind") not in {
                "model_input", "tool_call", "tool_output", "memory_read", "output"
            }:
                cancel_runtime()
                return stop("failed", {"type": "malformed_runtime_event"},
                            event="runtime.failed", data={"type": "malformed_runtime_event"})
            event_provenance = provenance(event.get("provenance"))
            depth = event.get("delegation_depth")
            if not isinstance(depth, int) or isinstance(depth, bool) or depth < 0:
                cancel_runtime()
                return stop("failed", {"type": "malformed_runtime_event"},
                            event="runtime.failed", data={"type": "malformed_runtime_event"})
            if depth > max_depth:
                cancel_runtime()
                failure = {"type": "delegation_depth", "max_depth": max_depth}
                return stop("denied", failure, event="delegation.denied", data=failure)
            context = {"kind": event["kind"], "provenance": event_provenance,
                       "delegation_depth": depth}
            field = "action" if event["kind"] == "tool_call" else "content"
            if field not in event:
                cancel_runtime()
                return stop("failed", {"type": "malformed_runtime_event"},
                            event="runtime.failed", data={"type": "malformed_runtime_event"})
            context[field] = deepcopy(event[field])
            checked, failure = apply_policy(context)
            if failure:
                cancel_runtime()
                return stop("denied", failure, event="policy.denied", data=failure)
            event[field] = deepcopy(checked.get(field))
            event["provenance"] = event_provenance
            if event["kind"] == "tool_call":
                try:
                    event["action"] = redactor.redact(deepcopy(event["action"]))
                    event["action"] = copy_json(
                        event["action"], field="redacted executable action JSON"
                    )
                except HarnessFailure:
                    raise
                except Exception as error:
                    raise RedactionFailure(error) from error
                if approval_gate is None:
                    cancel_runtime()
                    failure = {"type": "approval_failure", "reason": "missing_gate"}
                    return stop("denied", failure, event="tool.denied", data=failure)
                outcome = approval_gate.classify(
                    deepcopy(event["action"]), set(capabilities), deepcopy(event_provenance)
                )
                if cancelled():
                    cancel_runtime()
                    return stop("cancelled", {"type": "cancelled"}, event="run.cancelled")
                outcome_name = type(outcome).__name__
                if outcome_name == "DeniedAction":
                    cancel_runtime()
                    failure = {"type": "approval_denied", "reason": outcome.reason}
                    return stop("denied", failure, event="tool.denied", data=failure)
                if outcome_name == "ApprovalRequest":
                    audit("tool.awaiting_approval", {"digest": outcome.digest})
                    return GuardedResult("awaiting_approval", audit_records=records,
                                         pending_approval=outcome)
                if outcome_name != "ApprovedAction":
                    cancel_runtime()
                    failure = {"type": "approval_failure", "reason": "invalid_result"}
                    return stop("denied", failure, event="tool.denied", data=failure)
                event["action"] = deepcopy(outcome.action)
                audit("tool.approved", event)
                if cancelled():
                    cancel_runtime()
                    return stop("cancelled", {"type": "cancelled"}, event="run.cancelled")
                runtime.commit(deepcopy(event))
                audit("tool.committed", event)
            else:
                audit(event["kind"], event)
                if event["kind"] == "output":
                    try:
                        output = redactor.redact(deepcopy(event["content"]))
                        output = copy_json(output, field="redacted output JSON")
                    except HarnessFailure:
                        raise
                    except Exception as error:
                        raise RedactionFailure(error) from error
        audit("run.completed", {"steps": steps})
        return GuardedResult("completed", output, audit_records=records)
    except HarnessFailure:
        raise
    except AuditFailure as wrapped:
        cancel_runtime()
        error = wrapped.error
        return GuardedResult("failed", failure={"type": "audit_failure",
            "error_type": type(error).__name__, "message": safe_error_message(error)},
            audit_records=records)
    except RedactionFailure as wrapped:
        cancel_runtime()
        error = wrapped.error
        failure = {"type": "redaction_failure",
                   "error_type": type(error).__name__, "message": "redaction failed"}
        try:
            audit("redaction.failed", failure)
        except (AuditFailure, RedactionFailure):
            pass
        return GuardedResult("failed", failure=failure, audit_records=records)
    except Exception as error:
        cancel_runtime()
        failure = {"type": "runtime_failure", "error_type": type(error).__name__,
                   "message": safe_error_message(error)}
        try:
            audit("runtime.failed", failure)
        except AuditFailure as audit_wrapped:
            audit_error = audit_wrapped.error
            return GuardedResult("failed", failure={"type": "audit_failure",
                "error_type": type(audit_error).__name__,
                "message": safe_error_message(audit_error)}, audit_records=records)
        except RedactionFailure:
            return GuardedResult("failed", failure={"type": "redaction_failure",
                "error_type": "RedactionFailure", "message": "redaction failed"},
                audit_records=records)
        return GuardedResult("failed", failure=failure, audit_records=records)

class _ManualReLU(nn.Module):
    def forward(self, x):
        return x.clamp(min=0)

class MixtureOfExperts(nn.Module):
    def __init__(self, d_model, d_ff, num_experts, top_k=2):
        super().__init__()
        self.top_k = top_k
        self.router = nn.Linear(d_model, num_experts)
        self.experts = nn.ModuleList([
            nn.Sequential(nn.Linear(d_model, d_ff), _ManualReLU(), nn.Linear(d_ff, d_model))
            for _ in range(num_experts)
        ])

    def forward(self, x):
        orig_shape = x.shape
        if x.dim() == 3:
            B, S, D = x.shape
            x_flat = x.reshape(-1, D)
        else:
            x_flat = x
        logits = self.router(x_flat)
        top_vals, top_idx = logits.topk(self.top_k, dim=-1)
        weights = torch.softmax(top_vals, dim=-1)
        output = torch.zeros_like(x_flat)
        for k in range(self.top_k):
            for e in range(len(self.experts)):
                mask = (top_idx[:, k] == e)
                if mask.any():
                    output[mask] += weights[mask, k:k+1] * self.experts[e](x_flat[mask])
        return output.reshape(orig_shape)

def moe_capacity_dispatch(x, expert_indices, expert_weights, experts, capacity):
    if x.ndim != 2 or expert_indices.ndim != 2 or expert_weights.shape != expert_indices.shape:
        raise ValueError("x and route tensors have invalid shapes")
    if expert_indices.shape[0] != x.shape[0] or expert_indices.dtype != torch.long:
        raise ValueError("route tensors must align with tokens and indices must be long")
    if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 0 or not experts:
        raise ValueError("capacity and experts are invalid")
    if expert_indices.numel() and (int(expert_indices.min()) < 0 or int(expert_indices.max()) >= len(experts)):
        raise ValueError("expert index out of range")
    loads = [0 for _ in experts]
    routes = [[] for _ in experts]
    for token in range(expert_indices.shape[0]):
        for slot in range(expert_indices.shape[1]):
            expert_id = int(expert_indices[token, slot])
            if loads[expert_id] < capacity:
                routes[expert_id].append((token, slot))
                loads[expert_id] += 1
    output = torch.zeros_like(x)
    for expert_id, accepted in enumerate(routes):
        if not accepted:
            continue
        token_ids = torch.tensor([token for token, _ in accepted], device=x.device)
        slot_ids = torch.tensor([slot for _, slot in accepted], device=x.device)
        expert_output = experts[expert_id](x.index_select(0, token_ids))
        route_weights = expert_weights[token_ids, slot_ids].to(expert_output.dtype).unsqueeze(-1)
        output.index_add_(0, token_ids, expert_output * route_weights)
    accepted_count = sum(loads)
    return output, {"accepted": accepted_count, "dropped": expert_indices.numel() - accepted_count, "loads": loads}

import math
import torch

def muon_update(grad, momentum, beta=0.95, nesterov=True, ns_steps=5, eps=1e-7):
    if grad.ndim != 2 or momentum.shape != grad.shape:
        raise ValueError("grad and momentum must share one 2-D shape")
    if not 0 <= beta < 1 or ns_steps < 1:
        raise ValueError("need 0 <= beta < 1 and ns_steps >= 1")
    momentum.mul_(beta).add_(grad, alpha=1 - beta)
    G = (1 - beta) * grad + beta * momentum if nesterov else momentum.clone()

    a, b, c = 3.4445, -4.7750, 2.0315
    rows, cols = G.shape
    X = G / (G.norm() + eps)
    tall = rows > cols
    if tall:
        X = X.T
    for _ in range(ns_steps):
        A = X @ X.T
        B = b * A + c * A @ A
        X = a * X + B @ X
    if tall:
        X = X.T
    return X * math.sqrt(max(1.0, rows / cols))

import asyncio
import os


class FileMutationQueue:
    def __init__(self):
        self._tails = {}
        self._background = set()

    def active_keys(self):
        return set(self._tails)

    def _release(self, key, done):
        done.set()
        if self._tails.get(key) is done:
            del self._tails[key]

    async def run(self, path, fn):
        key = os.path.realpath(os.path.abspath(path))
        prev = self._tails.get(key)
        done = asyncio.Event()
        self._tails[key] = done
        if prev is not None:
            try:
                await prev.wait()
            except asyncio.CancelledError:
                async def hand_over():
                    await prev.wait()
                    self._release(key, done)

                task = asyncio.ensure_future(hand_over())
                self._background.add(task)
                task.add_done_callback(self._background.discard)
                raise
        try:
            return await fn()
        finally:
            self._release(key, done)

import re
import unicodedata

_SINGLE = dict.fromkeys(map(ord, "\u2018\u2019\u201a\u201b"), "'")
_DOUBLE = dict.fromkeys(map(ord, "\u201c\u201d\u201e\u201f"), '"')
_DASH = dict.fromkeys(map(ord, "\u2010\u2011\u2012\u2013\u2014\u2015\u2212"), "-")
_SPACE = dict.fromkeys([0x00A0, *range(0x2002, 0x200B), 0x202F, 0x205F, 0x3000], " ")
_TABLE = {**_SINGLE, **_DOUBLE, **_DASH, **_SPACE}


def _norm(text):
    text = unicodedata.normalize("NFKC", text)
    text = "\n".join(line.rstrip() for line in text.split("\n"))
    return text.translate(_TABLE)


def _to_lf(text):
    return text.replace("\r\n", "\n").replace("\r", "\n")


def _line_spans(text):
    spans, offset = [], 0
    for line in re.findall(r"[^\n]*\n|[^\n]+", text):
        spans.append((offset, offset + len(line)))
        offset += len(line)
    return spans


def _apply(text, replacements, offset=0):
    for start, length, new in sorted(replacements, reverse=True):
        start -= offset
        text = text[:start] + new + text[start + length:]
    return text


def apply_edits(content, edits):
    crlf_at, lf_at = content.find("\r\n"), content.find("\n")
    crlf = lf_at != -1 and crlf_at != -1 and crlf_at <= lf_at
    original = _to_lf(content)
    edits = [(_to_lf(e["old_text"]), _to_lf(e["new_text"])) for e in edits]
    if any(not old for old, _ in edits):
        raise ValueError("old_text must not be empty")

    fuzzy = any(old not in original and _norm(old) in _norm(original) for old, _ in edits)
    base = _norm(original) if fuzzy else original

    matches = []
    for old, new in edits:
        index, length = base.find(old), len(old)
        if index == -1:
            index, length = base.find(_norm(old)), len(_norm(old))
        if index == -1:
            raise ValueError("could not find old_text in the file")
        if _norm(base).count(_norm(old)) > 1:
            raise ValueError("old_text must be unique; add more context")
        matches.append((index, length, new))
    matches.sort()
    for (s1, l1, _), (s2, _, _) in zip(matches, matches[1:]):
        if s1 + l1 > s2:
            raise ValueError("edits overlap; merge them or target disjoint regions")

    if not fuzzy:
        result = _apply(base, matches)
    else:
        original_lines = re.findall(r"[^\n]*\n|[^\n]+", original)
        spans = _line_spans(base)
        groups = []
        for start, length, new in matches:
            first = next(i for i, (a, b) in enumerate(spans) if a <= start < b)
            last = first
            while spans[last][1] < start + length:
                last += 1
            if groups and first < groups[-1][1]:
                groups[-1][1] = max(groups[-1][1], last + 1)
                groups[-1][2].append((start, length, new))
            else:
                groups.append([first, last + 1, [(start, length, new)]])
        result, cursor = "", 0
        for first, end, reps in groups:
            result += "".join(original_lines[cursor:first])
            lo, hi = spans[first][0], spans[end - 1][1]
            result += _apply(base[lo:hi], reps, lo)
            cursor = end
        result += "".join(original_lines[cursor:])

    if result == original:
        raise ValueError("no changes: the replacements produced identical content")
    return result.replace("\n", "\r\n") if crlf else result

import json
import re

_VALID_ESCAPES = set('"\\/bfnrtu')
_NUMBER = re.compile(r"-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?")
_CONTROL = {"\b": "\\b", "\f": "\\f", "\n": "\\n", "\r": "\\r", "\t": "\\t"}
_MISSING = object()


class _Invalid(Exception):
    pass


def repair(text):
    out = []
    in_string = False
    i = 0
    while i < len(text):
        ch = text[i]
        if not in_string:
            out.append(ch)
            in_string = ch == '"'
            i += 1
            continue
        if ch == '"':
            out.append(ch)
            in_string = False
        elif ch == "\\":
            nxt = text[i + 1] if i + 1 < len(text) else None
            if nxt == "u" and re.fullmatch(r"[0-9a-fA-F]{4}", text[i + 2:i + 6]):
                out.append(text[i:i + 6])
                i += 6
                continue
            if nxt is not None and nxt in _VALID_ESCAPES:
                out.append("\\" + nxt)
                i += 2
                continue
            out.append("\\\\")
        elif ord(ch) < 0x20:
            out.append(_CONTROL.get(ch, f"\\u{ord(ch):04x}"))
        else:
            out.append(ch)
        i += 1
    return "".join(out)


def _partial(s):
    n = len(s)

    def ws(i):
        while i < n and s[i] in " \t\n\r":
            i += 1
        return i

    def string(i):
        j = i + 1
        while j < n:
            ch = s[j]
            if ch == '"':
                return json.loads(s[i:j + 1]), j + 1, True
            if ch == "\\":
                if j + 1 == n:
                    break
                esc = s[j + 1]
                if esc == "u":
                    digits = s[j + 2:j + 6]
                    if not re.fullmatch(r"[0-9a-fA-F]*", digits):
                        raise _Invalid()
                    if len(digits) < 4:
                        break
                    j += 6
                    continue
                if esc not in _VALID_ESCAPES:
                    raise _Invalid()
                j += 2
                continue
            if ord(ch) < 0x20:
                raise _Invalid()
            j += 1
        text = json.loads(s[i:j] + '"')
        if text and 0xD800 <= ord(text[-1]) <= 0xDBFF:
            text = text[:-1]
        return text, n, False

    def number(i):
        j = i
        while j < n and s[j] in "0123456789+-.eE":
            j += 1
        token = s[i:j]
        if j == n:
            token = token.rstrip("+-.eE")
            if _NUMBER.fullmatch(token):
                return json.loads(token), n, False
            return _MISSING, n, False
        if not _NUMBER.fullmatch(token):
            raise _Invalid()
        return json.loads(token), j, True

    def container(i, close, is_object):
        result = {} if is_object else []
        j = ws(i + 1)
        if j == n:
            return result, n, False
        if s[j] == close:
            return result, j + 1, True
        while True:
            j = ws(j)
            if j == n:
                return result, n, False
            key = None
            if is_object:
                if s[j] != '"':
                    raise _Invalid()
                key, j, done = string(j)
                if not done:
                    return result, n, False
                j = ws(j)
                if j == n:
                    return result, n, False
                if s[j] != ":":
                    raise _Invalid()
                j += 1
            item, j, done = value(j)
            if item is not _MISSING:
                if is_object:
                    result[key] = item
                else:
                    result.append(item)
            if not done:
                return result, n, False
            j = ws(j)
            if j == n:
                return result, n, False
            if s[j] == close:
                return result, j + 1, True
            if s[j] != ",":
                raise _Invalid()
            j += 1

    def value(i):
        i = ws(i)
        if i == n:
            return _MISSING, n, False
        ch = s[i]
        if ch == "{":
            return container(i, "}", True)
        if ch == "[":
            return container(i, "]", False)
        if ch == '"':
            return string(i)
        if ch == "-" or ch.isdigit():
            return number(i)
        for literal, parsed in (("true", True), ("false", False), ("null", None)):
            if s.startswith(literal, i):
                return parsed, i + len(literal), True
            if literal.startswith(s[i:]):
                return _MISSING, n, False
        raise _Invalid()

    result, end, done = value(0)
    if done and ws(end) != n:
        raise _Invalid()
    return {} if result is _MISSING else result


def parse_streaming_json(text):
    if not text or not text.strip():
        return {}
    try:
        return json.loads(text)
    except ValueError:
        pass
    fixed = repair(text)
    if fixed != text:
        try:
            return json.loads(fixed)
        except ValueError:
            pass
    for candidate in (text, fixed):
        try:
            return _partial(candidate)
        except (_Invalid, ValueError):
            continue
    return {}

NON_VISION_USER = "(image omitted: model does not support images)"
NON_VISION_TOOL = "(tool image omitted: model does not support images)"
NO_RESULT = "No result provided"


def _replace_images(content, placeholder):
    result = []
    previous_was_placeholder = False
    for block in content:
        if block["type"] == "image":
            if not previous_was_placeholder:
                result.append({"type": "text", "text": placeholder})
            previous_was_placeholder = True
            continue
        result.append(block)
        previous_was_placeholder = block.get("text") == placeholder
    return result


def transform_messages(messages, model, normalize_tool_call_id=None):
    supports_images = "image" in model["input"]
    id_map = {}
    transformed = []
    for msg in messages:
        if msg.get("content") is None:
            msg = {**msg, "content": []}
        role = msg["role"]
        if not supports_images:
            if role == "user" and isinstance(msg["content"], list):
                msg = {**msg, "content": _replace_images(msg["content"], NON_VISION_USER)}
            elif role == "toolResult":
                msg = {**msg, "content": _replace_images(msg["content"], NON_VISION_TOOL)}
        if role == "toolResult":
            new_id = id_map.get(msg["tool_call_id"])
            if new_id is not None and new_id != msg["tool_call_id"]:
                msg = {**msg, "tool_call_id": new_id}
        elif role == "assistant":
            same = (msg["provider"] == model["provider"] and msg["api"] == model["api"]
                    and msg["model"] == model["id"])
            content = []
            for block in msg["content"]:
                kind = block["type"]
                if kind == "thinking":
                    if block.get("redacted"):
                        if same:
                            content.append(block)
                        continue
                    if same and block.get("signature"):
                        content.append(block)
                        continue
                    if not block.get("thinking", "").strip():
                        continue
                    content.append(block if same else {"type": "text", "text": block["thinking"]})
                elif kind == "text":
                    content.append(block if same else {"type": "text", "text": block["text"]})
                elif kind == "toolCall":
                    call = block
                    if not same and "thought_signature" in call:
                        call = {k: v for k, v in call.items() if k != "thought_signature"}
                    if not same and normalize_tool_call_id is not None:
                        new_id = normalize_tool_call_id(block["id"], model, msg)
                        if new_id != block["id"]:
                            id_map[block["id"]] = new_id
                            call = {**call, "id": new_id}
                    content.append(call)
                else:
                    content.append(block)
            msg = {**msg, "content": content}
        transformed.append(msg)

    result = []
    pending = []
    answered = set()
    held = []

    def close():
        nonlocal pending, answered
        for call in pending:
            if call["id"] not in answered:
                result.append({"role": "toolResult", "tool_call_id": call["id"], "tool_name": call["name"],
                               "content": [{"type": "text", "text": NO_RESULT}], "is_error": True})
        pending, answered = [], set()
        result.extend(held)
        held.clear()

    for msg in transformed:
        role = msg["role"]
        if role == "assistant":
            close()
            if msg.get("stop_reason") in ("error", "aborted"):
                continue
            calls = [b for b in msg["content"] if b["type"] == "toolCall"]
            if calls:
                pending, answered = calls, set()
            result.append(msg)
        elif role == "toolResult":
            answered.add(msg["tool_call_id"])
            result.append(msg)
        elif role == "system":
            (held if pending else result).append(msg)
        elif role == "user":
            close()
            result.append(msg)
        else:
            result.append(msg)
    close()
    return result

import torch


def ppo_clipped_policy_loss(
    logprobs, old_logprobs, advantages, mask, clip_eps=0.2, dual_clip=None
):
    shapes = (logprobs.shape, old_logprobs.shape, advantages.shape, mask.shape)
    if len(set(shapes)) != 1:
        raise ValueError(f"all tensors must share a shape, got {shapes}")
    if clip_eps <= 0:
        raise ValueError(f"clip_eps must be positive, got {clip_eps}")
    if dual_clip is not None and dual_clip <= 1.0:
        raise ValueError(f"dual_clip must be greater than 1.0, got {dual_clip}")

    keep = mask.to(logprobs.dtype)
    denominator = keep.sum()
    if denominator == 0:
        return torch.zeros((), dtype=logprobs.dtype, device=logprobs.device)

    ratio = torch.exp(logprobs - old_logprobs)
    unclipped = ratio * advantages
    clipped = ratio.clamp(1.0 - clip_eps, 1.0 + clip_eps) * advantages
    per_token = -torch.min(unclipped, clipped)

    if dual_clip is not None:
        bounded = torch.min(per_token, -dual_clip * advantages)
        per_token = torch.where(advantages < 0, bounded, per_token)

    return (per_token * keep).sum() / denominator

import torch


def rollout_batch_assembly(prompt_ids, generation_ids, advantages, pad_id=0):
    batch_size = len(prompt_ids)
    if batch_size == 0:
        raise ValueError("the batch must hold at least one response")
    if len(generation_ids) != batch_size:
        raise ValueError(
            f"prompt_ids has {batch_size} rows but generation_ids has {len(generation_ids)}"
        )
    if advantages.ndim != 1 or advantages.shape[0] != batch_size:
        raise ValueError(
            f"advantages must have shape ({batch_size},), got {tuple(advantages.shape)}"
        )

    device = advantages.device
    prompt_lens = torch.tensor([len(p) for p in prompt_ids], device=device)
    gen_lens = torch.tensor([len(g) for g in generation_ids], device=device)
    total_lens = prompt_lens + gen_lens
    width = int(total_lens.max())

    input_ids = torch.full((batch_size, width), pad_id, dtype=torch.long, device=device)
    for row, (prompt, generation) in enumerate(zip(prompt_ids, generation_ids)):
        tokens = list(prompt) + list(generation)
        if tokens:
            input_ids[row, : len(tokens)] = torch.tensor(
                tokens, dtype=torch.long, device=device
            )

    positions = torch.arange(width, device=device).unsqueeze(0)
    mask = (positions >= prompt_lens.unsqueeze(-1)) & (positions < total_lens.unsqueeze(-1))
    token_advantages = advantages.unsqueeze(-1) * mask.to(advantages.dtype)

    return {
        "input_ids": input_ids,
        "mask": mask,
        "token_advantages": token_advantages,
        "lengths": gen_lens,
    }

def rollout_train_boundary(trajectories):
    output = {"input_ids": [], "loss_mask": [], "advantages": [], "episode_ids": []}
    for episode_id, trajectory in enumerate(trajectories):
        try:
            ids = trajectory["response_ids"]
            mask = trajectory["response_mask"]
            rewards = trajectory["rewards"]
        except (KeyError, TypeError):
            raise ValueError("trajectory is missing a required field")
        if not ids or not rewards or len(ids) != len(mask):
            raise ValueError("trajectory fields must be non-empty and aligned")
        total_reward = sum(float(reward) for reward in rewards)
        for token_id, trainable in zip(ids, mask):
            output["input_ids"].append(token_id)
            output["episode_ids"].append(episode_id)
            output["loss_mask"].append(bool(trainable))
            output["advantages"].append(total_reward if trainable else 0.0)
    return output

def rollout_weight_sync_staleness(samples, trainer_version, serving_version, max_staleness, in_flight, sync_weights):
    for value in (trainer_version, serving_version, max_staleness, in_flight):
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ValueError("versions and counts must be non-negative integers")
    if serving_version > trainer_version:
        raise ValueError("serving version is ahead of trainer")
    train, retry, dropped, seen = [], [], [], set()
    for sample in samples:
        try:
            sample_id = sample["sample_id"]
            version = sample["weight_version"]
            status = sample["status"]
        except (KeyError, TypeError):
            raise ValueError("malformed sample")
        if sample_id in seen or status not in ("complete", "aborted", "failed"):
            raise ValueError("duplicate id or unknown status")
        seen.add(sample_id)
        if not isinstance(version, int) or isinstance(version, bool) or version < 0 or version > trainer_version:
            raise ValueError("invalid sample version")
        if status == "failed":
            dropped.append(sample)
        elif status == "aborted" or trainer_version - version > max_staleness:
            retry.append(sample)
        else:
            train.append(sample)
    sync_deferred = serving_version != trainer_version and in_flight > 0
    if serving_version != trainer_version and not sync_deferred:
        sync_weights(trainer_version)
        serving_version = trainer_version
    return {
        "train": train, "retry": retry, "dropped": dropped,
        "serving_version": serving_version, "sync_deferred": sync_deferred,
    }

def speculative_decode(target_probs, draft_probs, draft_tokens):
    K = len(draft_tokens)
    accepted = []
    for i in range(K):
        t = draft_tokens[i].item()
        ratio = target_probs[i, t] / max(draft_probs[i, t].item(), 1e-10)
        if torch.rand(1).item() < min(1.0, ratio.item()):
            accepted.append(t)
        else:
            adjusted = torch.clamp(target_probs[i] - draft_probs[i], min=0)
            s = adjusted.sum()
            if s > 0:
                adjusted = adjusted / s
            else:
                adjusted = torch.ones_like(adjusted) / adjusted.shape[0]
            accepted.append(torch.multinomial(adjusted, 1).item())
            return accepted
    return accepted

class TensorParallelMLP(nn.Module):
    def __init__(self, d_model, d_ff, world_size):
        super().__init__()
        self.world_size = world_size
        shard_size = d_ff // world_size
        # Column-parallel: W1 shards (d_model, shard_size) each
        self.w1_shards = nn.ParameterList([
            nn.Parameter(torch.randn(d_model, shard_size) * (2 / d_model) ** 0.5)
            for _ in range(world_size)
        ])
        # Row-parallel: W2 shards (shard_size, d_model) each
        self.w2_shards = nn.ParameterList([
            nn.Parameter(torch.randn(shard_size, d_model) * (2 / d_ff) ** 0.5)
            for _ in range(world_size)
        ])

    def forward(self, x):
        # Column-parallel forward + row-parallel + all-reduce (sum)
        output = None
        for w1, w2 in zip(self.w1_shards, self.w2_shards):
            z = x @ w1
            h = z * 0.5 * (1.0 + torch.erf(z / (2.0 ** 0.5)))  # GELU
            partial = h @ w2                        # (B, d_model)
            output = partial if output is None else output + partial
        return output

def schedule_tool_calls(calls, execute, max_parallel):
    if not isinstance(max_parallel, int) or isinstance(max_parallel, bool) or max_parallel < 1:
        raise ValueError("max_parallel must be a positive integer")

    by_id = {}
    for call in calls:
        call_id = call.get("id")
        if not isinstance(call_id, str):
            raise ValueError("every call needs a string id")
        if call_id in by_id:
            raise ValueError(f"duplicate id {call_id!r}")
        if not isinstance(call.get("deps"), list):
            raise ValueError(f"deps of {call_id!r} must be a list")
        by_id[call_id] = call

    dependents = {call_id: [] for call_id in by_id}
    indegree = {call_id: 0 for call_id in by_id}
    for call_id, call in by_id.items():
        for dep in call["deps"]:
            if dep == call_id:
                raise ValueError(f"{call_id!r} depends on itself")
            if dep not in by_id:
                raise ValueError(f"{call_id!r} depends on unknown id {dep!r}")
            dependents[dep].append(call_id)
            indegree[call_id] += 1

    frontier = [call_id for call_id, degree in indegree.items() if degree == 0]
    emitted = 0
    remaining = dict(indegree)
    while frontier:
        current = frontier.pop()
        emitted += 1
        for child in dependents[current]:
            remaining[child] -= 1
            if remaining[child] == 0:
                frontier.append(child)
    if emitted != len(by_id):
        raise ValueError("the dependencies contain a cycle")

    status = {call_id: "pending" for call_id in by_id}
    results, errors, rounds = {}, {}, []

    while True:
        ready = [
            call["id"] for call in calls
            if status[call["id"]] == "pending"
            and all(status[dep] == "succeeded" for dep in call["deps"])
        ][:max_parallel]
        if not ready:
            break
        rounds.append(ready)
        for call_id in ready:
            call = by_id[call_id]
            dep_results = {dep: results[dep] for dep in call["deps"]}
            try:
                results[call_id] = execute(call, dep_results)
                status[call_id] = "running"
            except Exception as error:
                errors[call_id] = error
                status[call_id] = "failed"
                stack = list(dependents[call_id])
                while stack:
                    child = stack.pop()
                    if status[child] == "pending":
                        status[child] = "skipped"
                        stack.extend(dependents[child])
        for call_id in ready:
            if status[call_id] == "running":
                status[call_id] = "succeeded"

    skipped = [call["id"] for call in calls if status[call["id"]] == "skipped"]
    return {"results": results, "errors": errors, "skipped": skipped, "rounds": rounds}

import json


class ToolCallStreamParser:
    def __init__(self, open_tag="<tool_call>", close_tag="</tool_call>"):
        for tag in (open_tag, close_tag):
            if not isinstance(tag, str) or not tag:
                raise ValueError("tags must be non-empty strings")
        if open_tag == close_tag:
            raise ValueError("the open and close tags must differ")
        self._open = open_tag
        self._close = close_tag
        self._buffer = ""
        self._inside = False
        self._finished = False

    def feed(self, chunk):
        if self._finished:
            raise ValueError("feed called after finish")
        if not isinstance(chunk, str):
            raise ValueError("chunk must be a string")
        self._buffer += chunk
        events = []
        while True:
            if self._inside:
                end = self._buffer.find(self._close)
                if end < 0:
                    break
                body = self._buffer[:end]
                self._buffer = self._buffer[end + len(self._close):]
                self._inside = False
                events.append(self._parse(body))
                continue
            start = self._buffer.find(self._open)
            if start >= 0:
                if start:
                    events.append({"type": "text", "content": self._buffer[:start]})
                self._buffer = self._buffer[start + len(self._open):]
                self._inside = True
                continue
            held = self._held_back(self._buffer)
            release = self._buffer[: len(self._buffer) - held]
            if release:
                events.append({"type": "text", "content": release})
            self._buffer = self._buffer[len(release):]
            break
        return events

    def finish(self):
        if self._finished:
            raise ValueError("finish called twice")
        self._finished = True
        events = []
        if self._inside:
            events.append({"type": "error", "raw": self._buffer, "reason": "unterminated"})
        elif self._buffer:
            events.append({"type": "text", "content": self._buffer})
        self._buffer = ""
        return events

    def _held_back(self, text):
        for size in range(min(len(text), len(self._open) - 1), 0, -1):
            if self._open.startswith(text[-size:]):
                return size
        return 0

    @staticmethod
    def _parse(body):
        try:
            payload = json.loads(body)
        except ValueError:
            return {"type": "error", "raw": body, "reason": "invalid_json"}
        if not isinstance(payload, dict):
            return {"type": "error", "raw": body, "reason": "not_a_call"}
        name = payload.get("name")
        arguments = payload.get("arguments", {})
        if not isinstance(name, str) or not name or not isinstance(arguments, dict):
            return {"type": "error", "raw": body, "reason": "not_a_call"}
        return {"type": "tool_call", "name": name, "arguments": arguments}

def verl_dataproto_filter_chunk(data, chunks):
    import torch
    if not isinstance(chunks, int) or isinstance(chunks, bool) or chunks <= 0:
        raise ValueError("chunks must be positive")
    mask = data.batch["response_mask"]
    if mask.ndim != 2 or mask.dtype != torch.bool:
        raise ValueError("response_mask must be a boolean matrix")
    indices = torch.nonzero(mask.any(dim=1), as_tuple=False).flatten().tolist()
    if not indices or len(indices) % chunks:
        raise ValueError("selected rows cannot form equal chunks")
    return data.select_idxs(indices).chunk(chunks)

import torch


def vineppo_mc_value(rollout_rewards, final_reward):
    if rollout_rewards.ndim != 2:
        raise ValueError(
            f"rollout_rewards must be two-dimensional, got {tuple(rollout_rewards.shape)}"
        )
    states, continuations = rollout_rewards.shape
    if states == 0 or continuations == 0:
        raise ValueError(
            f"need at least one state and one continuation, got {tuple(rollout_rewards.shape)}"
        )

    values = rollout_rewards.mean(dim=-1)
    bootstrap = final_reward.reshape(1).to(values.dtype)
    next_value = torch.cat([values[1:], bootstrap])
    return values, next_value - values
